SOURCES.AnimationBuilder = [===[
--[[
	Pose math shared by PoseAnimator (which plays the animations in game),
	plus an optional KeyframeSequence export of AnimationData for anyone who
	wants to open a move in Roblox's Animation Editor. The game itself never
	needs uploaded animation assets.
]]

local AnimationData = require(script.Parent.AnimationData)

local AnimationBuilder = {}

-- Joint rest rotations of the standard R6 rig (C0 and C1 share them).
local ROOT_ROTATION = CFrame.fromOrientation(-math.pi / 2, math.pi, 0)
local RIGHT_ROTATION = CFrame.fromOrientation(0, math.pi / 2, 0)
local LEFT_ROTATION = CFrame.fromOrientation(0, -math.pi / 2, 0)

local JOINTS = {
	Torso = { part = "Torso", rotation = ROOT_ROTATION },
	Head = { part = "Head", rotation = ROOT_ROTATION },
	RightArm = { part = "Right Arm", rotation = RIGHT_ROTATION },
	LeftArm = { part = "Left Arm", rotation = LEFT_ROTATION },
	RightLeg = { part = "Right Leg", rotation = RIGHT_ROTATION },
	LeftLeg = { part = "Left Leg", rotation = LEFT_ROTATION },
}

local LIMBS = { "Head", "RightArm", "LeftArm", "RightLeg", "LeftLeg" }

-- Pose easing only supports a few curves; map the authored names onto them.
local EASING = {
	Linear = Enum.PoseEasingStyle.Linear,
	Constant = Enum.PoseEasingStyle.Constant,
	Quad = Enum.PoseEasingStyle.CubicV2,
	Cubic = Enum.PoseEasingStyle.CubicV2,
	Quart = Enum.PoseEasingStyle.CubicV2,
	Quint = Enum.PoseEasingStyle.CubicV2,
	Exponential = Enum.PoseEasingStyle.CubicV2,
	Circular = Enum.PoseEasingStyle.CubicV2,
	Back = Enum.PoseEasingStyle.CubicV2,
	Sine = Enum.PoseEasingStyle.CubicV2,
	Elastic = Enum.PoseEasingStyle.Elastic,
	Bounce = Enum.PoseEasingStyle.Bounce,
}

-- PoseAnimator has an in-between priority Roblox doesn't.
local PRIORITY = {
	MovementOverlay = Enum.AnimationPriority.Movement,
}

-- Converts a parent-space pose into the Motor6D.Transform the pose represents.
function AnimationBuilder.toTransform(joint, value)
	local rx, ry, rz = math.rad(value[1] or 0), math.rad(value[2] or 0), math.rad(value[3] or 0)
	local offset = CFrame.new(value[4] or 0, value[5] or 0, value[6] or 0) * CFrame.Angles(rx, ry, rz)
	local rotation = JOINTS[joint].rotation
	return rotation:Inverse() * offset * rotation
end

local function usedJoints(data)
	local used = {}
	for _, key in ipairs(data.keys) do
		for joint in pairs(key.pose) do
			used[joint] = true
		end
	end
	return used
end

local function makePose(joint, value, used, key)
	local pose = Instance.new("Pose")
	pose.Name = JOINTS[joint].part
	if used and value then
		pose.CFrame = AnimationBuilder.toTransform(joint, value)
		pose.Weight = 1
	else
		pose.Weight = 0
	end
	pose.EasingStyle = EASING[key.ease or "Linear"] or Enum.PoseEasingStyle.Linear
	pose.EasingDirection = Enum.PoseEasingDirection[key.dir or "In"]
	return pose
end

function AnimationBuilder.build(name)
	local data = AnimationData[name]
	assert(data, "Unknown animation " .. tostring(name))

	local sequence = Instance.new("KeyframeSequence")
	sequence.Name = name
	sequence.Loop = data.looped == true
	local priority = data.priority or "Action"
	sequence.Priority = PRIORITY[priority] or Enum.AnimationPriority[priority]

	local used = usedJoints(data)
	local last = {}

	for _, key in ipairs(data.keys) do
		for joint in pairs(used) do
			if key.pose[joint] then
				last[joint] = key.pose[joint]
			end
		end

		local keyframe = Instance.new("Keyframe")
		keyframe.Time = key.t

		local root = Instance.new("Pose")
		root.Name = "HumanoidRootPart"
		root.Weight = 0

		local torso = makePose("Torso", last.Torso or { 0, 0, 0 }, used.Torso, key)
		for _, joint in ipairs(LIMBS) do
			if used[joint] then
				makePose(joint, last[joint] or { 0, 0, 0 }, true, key).Parent = torso
			end
		end
		torso.Parent = root
		root.Parent = keyframe

		if data.markers then
			for markerName, time in pairs(data.markers) do
				if math.abs(time - key.t) < 1e-4 then
					local marker = Instance.new("KeyframeMarker")
					marker.Name = markerName
					marker.Parent = keyframe
				end
			end
		end

		keyframe.Parent = sequence
	end

	return sequence
end

return AnimationBuilder
]===]

SOURCES.AnimationData = [===[
--[[
	R6 fighting animations, authored as pose data. PoseAnimator plays them
	directly on the joints (no uploaded assets); AnimationBuilder can export
	any of them as a KeyframeSequence for the Animation Editor.

	Style: battlegrounds-style, deliberately overanimated. Every strike has
	a wind-up, a near-instant snap into the hit, a short hang on the impact
	pose, an overshoot on the way back and a settle into guard. The whole
	body sells each move: hips drop, the torso twists and steps in, the head
	counter-rotates to keep eyes on the target, the off hand chambers.

	Each joint pose is { pitch, yaw, roll, x, y, z } in degrees / studs,
	expressed in the parent part's space at the joint pivot:
	  Torso is relative to HumanoidRootPart, limbs and Head are relative to Torso.
	  pitch +  = limb swings forward/up (Torso: leans back, Head: looks up)
	  yaw   +  = turns left (on a hanging limb: twists it)
	  roll  +  = limb end swings toward +X (right); Torso/Head tilt left
	  x/y/z    = shift right / up / back (Torso translation moves the whole body)
	A limb's world angle is roughly the torso's pitch plus its own, so a torso
	leaning forward 30 needs its legs pitched +30 to stay vertical.

	Keys: `ease`/`dir` shape the curve from that key to the next one. Any
	Roblox EasingStyle works (Back overshoots, Quart/Quint snap, Sine floats).

	group:
	  base    - locomotion (Stance, Walk, Run, Jump, Fall), driven by the client
	  hold    - looping holds (block), stopped explicitly
	  action  - attacks, dashes, feints; replaces other action/react/hold tracks
	  react   - hit reactions and stuns; replaces action/react/hold tracks
	  overlay - plays on top without stopping anything

	holdLast: a non-looping clip that freezes on its last frame until stopped.
	trail:    which limbs get swing trails between the Swing and Hit markers.

	markers become KeyframeMarkers. `Hit` is the impact frame the server uses,
	`recover` is when the attacker can act again.
]]

------------------------------------------------------------------------
-- Shared poses

-- Fighting stance: sitting low on the legs, lead (left) shoulder forward,
-- rear fist at the chin, lead fist out front.
local GUARD = {
	Torso = { -8, -20, 0, 0, -0.2, 0 },
	Head = { 8, 18, 0 },
	RightArm = { 100, 0, -42, 0, 0, 0.1 },
	LeftArm = { 108, 0, 28, 0, 0, -0.05 },
	RightLeg = { 2, 0, 9 },
	LeftLeg = { 24, 0, -5 },
}

-- Crossed arms in front of the face, chin tucked. No legs, so the walk
-- cycle keeps running underneath while blocking.
local BLOCK = {
	Torso = { -12, -6, 0, 0, -0.3, 0 },
	Head = { -10, 4, 0 },
	RightArm = { 118, 0, -58, 0, 0, 0.15 },
	LeftArm = { 112, 0, 52, 0, 0, 0.05 },
}

-- Legs tucked under for air moves.
local AIR_LEGS = {
	RightLeg = { 46, 0, 8 },
	LeftLeg = { 14, 0, -8 },
}

local function pose(...)
	local result = {}
	for _, part in ipairs({ ... }) do
		for joint, value in pairs(part) do
			result[joint] = value
		end
	end
	return result
end

local MIRROR = {
	Torso = "Torso",
	Head = "Head",
	RightArm = "LeftArm",
	LeftArm = "RightArm",
	RightLeg = "LeftLeg",
	LeftLeg = "RightLeg",
}

-- Left/right mirror of a pose.
local function mirror(p)
	local result = {}
	for joint, v in pairs(p) do
		result[MIRROR[joint]] = { v[1], -(v[2] or 0), -(v[3] or 0), -(v[4] or 0), v[5] or 0, v[6] or 0 }
	end
	return result
end

local function mirrorKeys(keys)
	local result = {}
	for i, key in ipairs(keys) do
		result[i] = { t = key.t, ease = key.ease, dir = key.dir, pose = mirror(key.pose) }
	end
	return result
end

local AIR_GUARD = pose(GUARD, AIR_LEGS, { Torso = { -4, -14, 0 } })

-- GUARD without the legs, for overlays that leave the lower body alone.
local GUARD_UPPER = {
	Torso = GUARD.Torso,
	Head = GUARD.Head,
	RightArm = GUARD.RightArm,
	LeftArm = GUARD.LeftArm,
}

