SOURCES.Effects = [===[
--[[
	Client-side combat VFX and sound, battlegrounds style. Regular hits stay
	clean: the struck body flashes (a Highlight) with a small crisp spark.
	The big moves (finishers, criticals, launchers, slams, parries, guard
	breaks) add shock rings, streaks and debris. Dashes leave afterimages and
	wind rings; slams crack the ground into a crater of rocks.

	Most shapes are procedural (neon parts animated every frame), so they need
	no uploads. The custom textures in Config.Textures add sparks, smoke and
	flipbook impacts on top. The slash skill's visuals are unchanged.
]]

local CollectionService = game:GetService("CollectionService")
local ContentProvider = game:GetService("ContentProvider")
local Debris = game:GetService("Debris")
local RunService = game:GetService("RunService")

local Config = require(script.Parent.Config)

local TEX = Config.Textures
local FLAT = Vector3.new(1, 0, 1)

local Effects = {}

local random = Random.new()

local function pick(list)
	return list[random:NextInteger(1, #list)]
end

function Effects.preload()
	local assets = {}
	for _, list in pairs(Config.Sounds) do
		for _, id in ipairs(list) do
			local sound = Instance.new("Sound")
			sound.SoundId = id
			table.insert(assets, sound)
		end
	end
	for _, id in pairs(TEX) do
		local decal = Instance.new("Decal")
		decal.Texture = id
		table.insert(assets, decal)
	end
	task.spawn(function()
		ContentProvider:PreloadAsync(assets)
	end)
end

local function anchorAt(position, lifetime)
	local attachment = Instance.new("Attachment")
	attachment.WorldPosition = position
	attachment.Parent = workspace.Terrain
	Debris:AddItem(attachment, lifetime)
	return attachment
end

function Effects.sound(kind, parent, volume, pitch)
	local list = Config.Sounds[kind]
	if not list then
		return
	end
	local sound = Instance.new("Sound")
	sound.SoundId = pick(list)
	sound.Volume = volume or 0.6
	sound.PlaybackSpeed = (pitch or 1) * random:NextNumber(0.94, 1.06)
	sound.RollOffMinDistance = 8
	sound.RollOffMaxDistance = 90
	sound.Parent = parent
	sound:Play()
	Debris:AddItem(sound, 4)
end

------------------------------------------------------------------------
-- Procedural building blocks

local fxFolder

local function folder()
	if not fxFolder or not fxFolder.Parent then
		fxFolder = Instance.new("Folder")
		fxFolder.Name = "CombatFX"
		fxFolder.Parent = workspace
	end
	return fxFolder
end

local function fxPart(color, material, shape)
	local part = Instance.new("Part")
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Locked = true
	part.TopSurface = Enum.SurfaceType.Smooth
	part.BottomSurface = Enum.SurfaceType.Smooth
	part.Material = material or Enum.Material.Neon
	part.Color = color or Color3.new(1, 1, 1)
	if shape then
		part.Shape = shape
	end
	part.Parent = folder()
	return part
end

-- Runs `step(alpha, dt)` every frame for `duration`, then `done()`.
local function animate(duration, step, done)
	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function(dt)
		local alpha = math.min(1, (os.clock() - start) / duration)
		local ok = pcall(step, alpha, dt)
		if alpha >= 1 or not ok then
			connection:Disconnect()
			if done then
				done()
			end
		end
	end)
end

local function easeOut(alpha, power)
	return 1 - (1 - alpha) ^ (power or 3)
end

-- A CFrame at `position` whose LookVector is `normal`.
local function facing(position, normal)
	normal = normal.Magnitude > 0.001 and normal.Unit or Vector3.yAxis
	local up = math.abs(normal.Y) > 0.95 and Vector3.xAxis or Vector3.yAxis
	local right = normal:Cross(up).Unit
	return CFrame.fromMatrix(position, right, right:Cross(normal), -normal)
end

-- A random direction within `spread` degrees of `direction`.
local function cone(direction, spread)
	local basis = facing(Vector3.zero, direction)
	local theta = math.rad(random:NextNumber(0, spread))
	local phi = random:NextNumber(0, math.pi * 2)
	return basis:VectorToWorldSpace(Vector3.new(
		math.sin(theta) * math.cos(phi),
		math.sin(theta) * math.sin(phi),
		-math.cos(theta)
	))
end

-- Expanding neon ball that fades out: the core of every impact.
local function burst(position, color, size0, size1, duration, transparency)
	local ball = fxPart(color, Enum.Material.Neon, Enum.PartType.Ball)
	ball.Size = Vector3.one * size0
	ball.CFrame = CFrame.new(position)
	local t0 = transparency or 0
	animate(duration, function(alpha)
		local size = size0 + (size1 - size0) * easeOut(alpha, 4)
		ball.Size = Vector3.one * size
		ball.Transparency = t0 + (1 - t0) * alpha ^ 1.4
	end, function()
		ball:Destroy()
	end)
end

-- Segmented shock ring lying in the plane of `cf` (axis = cf.LookVector).
local function ring(cf, color, r0, r1, thickness, duration, transparency, segments)
	segments = segments or 20
	local t0 = transparency or 0.1
	local parts = {}
	for i = 1, segments do
		parts[i] = fxPart(color)
	end
	animate(duration, function(alpha)
		local eased = easeOut(alpha, 3)
		local radius = r0 + (r1 - r0) * eased
		local width = thickness * (1 - alpha * 0.75)
		local length = (2 * math.pi * radius / segments) * 1.08
		local fade = t0 + (1 - t0) * alpha ^ 1.6
		for i, part in ipairs(parts) do
			local angle = (i / segments) * math.pi * 2
			part.Size = Vector3.new(width, length, width * 0.6)
			part.CFrame = cf * CFrame.Angles(0, 0, angle) * CFrame.new(radius, 0, 0)
			part.Transparency = fade
		end
	end, function()
		for _, part in ipairs(parts) do
			part:Destroy()
		end
	end)
end

-- Thin neon lines shooting out of an impact.
local function streaks(position, direction, count, color, length, distance, spread, duration, width)
	local lines = {}
	for i = 1, count do
		local dir = direction and cone(direction, spread) or cone(Vector3.yAxis, 180)
		lines[i] = { part = fxPart(color), dir = dir, length = length * random:NextNumber(0.6, 1.2), distance = distance * random:NextNumber(0.7, 1.15) }
	end
	width = width or 0.12
	animate(duration, function(alpha)
		local eased = easeOut(alpha, 2.5)
		for _, line in ipairs(lines) do
			local len = math.max(0.05, line.length * math.min(1, alpha * 6) * (1 - alpha) ^ 0.6)
			local centre = position + line.dir * (0.4 + line.distance * eased + len / 2)
			line.part.Size = Vector3.new(width * (1 - alpha * 0.6), width * (1 - alpha * 0.6), len)
			line.part.CFrame = CFrame.lookAt(centre, centre + line.dir)
			line.part.Transparency = alpha ^ 2
		end
	end, function()
		for _, line in ipairs(lines) do
			line.part:Destroy()
		end
	end)
end

-- Neon wedges blown outward with gravity (guard break).
local function shards(position, direction, count, color)
	local pieces = {}
	for i = 1, count do
		local part = Instance.new("WedgePart")
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Material = Enum.Material.Neon
		part.Color = color
		part.Size = Vector3.new(0.08, random:NextNumber(0.3, 0.8), random:NextNumber(0.3, 0.9))
		part.CFrame = CFrame.new(position) * CFrame.Angles(random:NextNumber(0, 6.3), random:NextNumber(0, 6.3), 0)
		part.Parent = folder()
		local dir = direction and cone(direction, 70) or cone(Vector3.yAxis, 180)
		pieces[i] = {
			part = part,
			velocity = dir * random:NextNumber(18, 34) + Vector3.new(0, random:NextNumber(4, 12), 0),
			spin = CFrame.Angles(random:NextNumber(-0.4, 0.4), random:NextNumber(-0.4, 0.4), random:NextNumber(-0.4, 0.4)),
		}
	end
	animate(0.7, function(alpha, dt)
		for _, piece in ipairs(pieces) do
			piece.velocity += Vector3.new(0, -70, 0) * dt
			piece.velocity *= 1 - math.min(1, dt * 2)
			piece.part.CFrame = (piece.part.CFrame + piece.velocity * dt) * piece.spin
			piece.part.Transparency = alpha ^ 2
		end
	end, function()
		for _, piece in ipairs(pieces) do
			piece.part:Destroy()
		end
	end)
end

------------------------------------------------------------------------
-- Ground

local function groundParams()
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ignore = { folder() }
	for _, model in ipairs(CollectionService:GetTagged("Combatant")) do
		table.insert(ignore, model)
	end
	params.FilterDescendantsInstances = ignore
	return params
end

-- Ground position, material and colour under `position`, or nil.
local function groundAt(position, depth)
	local result = workspace:Raycast(position + Vector3.new(0, 2, 0), Vector3.new(0, -(depth or 10), 0), groundParams())
	if not result then
		return nil
	end
	local color
	if result.Instance:IsA("Terrain") then
		local ok, terrainColor = pcall(function()
			return workspace.Terrain:GetMaterialColor(result.Material)
		end)
		color = ok and terrainColor or Color3.fromRGB(110, 105, 100)
	elseif result.Instance:IsA("BasePart") then
		color = result.Instance.Color
	else
		color = Color3.fromRGB(110, 105, 100)
	end
	return result.Position, result.Material, color
end

local function rockPart(material, color, size)
	local part = fxPart(color, Enum.Material.Slate)
	pcall(function()
		part.Material = material
	end)
	part.Size = size
	return part
end

-- Chunks of ground thrown up in arcs.
local function debris(position, count, material, color, power)
	local pieces = {}
	for i = 1, count do
		local s = random:NextNumber(0.35, 0.9)
		local part = rockPart(material, color, Vector3.new(s, s * random:NextNumber(0.6, 1), s))
		part.CFrame = CFrame.new(position) * CFrame.Angles(random:NextNumber(0, 6.3), random:NextNumber(0, 6.3), 0)
		local angle = random:NextNumber(0, math.pi * 2)
		pieces[i] = {
			part = part,
			velocity = Vector3.new(math.cos(angle), 0, math.sin(angle)) * random:NextNumber(8, 18) * power
				+ Vector3.new(0, random:NextNumber(18, 34) * power, 0),
			spin = CFrame.Angles(random:NextNumber(-0.3, 0.3), random:NextNumber(-0.3, 0.3), random:NextNumber(-0.3, 0.3)),
			floor = position.Y,
		}
	end
	animate(1.4, function(alpha, dt)
		for _, piece in ipairs(pieces) do
			if piece.velocity then
				piece.velocity += Vector3.new(0, -110, 0) * dt
				local cf = (piece.part.CFrame + piece.velocity * dt) * piece.spin
				if cf.Position.Y < piece.floor + 0.2 and piece.velocity.Y < 0 then
					piece.velocity = nil -- landed
					cf = CFrame.new(cf.Position.X, piece.floor + 0.2, cf.Position.Z) * cf.Rotation
				end
				piece.part.CFrame = cf
			end
			piece.part.Transparency = math.clamp((alpha - 0.7) / 0.3, 0, 1)
		end
	end, function()
		for _, piece in ipairs(pieces) do
			piece.part:Destroy()
		end
	end)
end

-- Rocks bursting up in a circle around an impact, then sinking away.
local function crater(position, radius, count)
	local ground, material, color = groundAt(position, 14)
	if not ground then
		return
	end
	local rocks = {}
	local offset = random:NextNumber(0, math.pi * 2)
	for i = 1, count do
		local angle = offset + (i / count) * math.pi * 2 + random:NextNumber(-0.15, 0.15)
		local dir = Vector3.new(math.cos(angle), 0, math.sin(angle))
		local size = Vector3.new(random:NextNumber(1.3, 2.4), random:NextNumber(1.1, 2), random:NextNumber(1.3, 2.4))
		local rest = CFrame.lookAt(ground + dir * radius * random:NextNumber(0.85, 1.15), ground + dir * (radius + 5))
			* CFrame.Angles(math.rad(random:NextNumber(25, 50)), 0, math.rad(random:NextNumber(-20, 20)))
		local part = rockPart(material, color, size)
		part.CFrame = rest - Vector3.new(0, 2.5, 0)
		rocks[i] = { part = part, rest = rest }
	end
	animate(0.14, function(alpha)
		for _, rock in ipairs(rocks) do
			rock.part.CFrame = rock.rest - Vector3.new(0, 2.5 * (1 - easeOut(alpha, 3)), 0)
		end
	end)
	task.delay(1.8, function()
		animate(0.6, function(alpha)
			for _, rock in ipairs(rocks) do
				rock.part.CFrame = rock.rest - Vector3.new(0, 2.5 * alpha * alpha, 0)
				rock.part.Transparency = alpha ^ 3
			end
		end, function()
			for _, rock in ipairs(rocks) do
				rock.part:Destroy()
			end
		end)
	end)
	debris(ground, math.floor(count * 0.8), material, color, 1)
end

------------------------------------------------------------------------
-- Flipbook billboard: steps through a 4x4 sheet while growing.

local function flipbook(parent, texture, options)
	local duration = options.duration or 0.35
	local gui = Instance.new("BillboardGui")
	gui.Size = UDim2.fromScale(options.size0, options.size0)
	gui.LightInfluence = 0
	gui.AlwaysOnTop = options.onTop == true
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.Adornee = parent
	gui.Parent = parent

	local image = Instance.new("ImageLabel")
	image.BackgroundTransparency = 1
	image.Size = UDim2.fromScale(1, 1)
	image.Image = texture
	image.ImageColor3 = options.color or Color3.new(1, 1, 1)
	image.ImageTransparency = options.transparency or 0
	image.ImageRectSize = Vector2.new(256, 256)
	image.Rotation = options.rotation or random:NextNumber(0, 360)
	image.Parent = gui

	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function()
		local alpha = (os.clock() - start) / duration
		if alpha >= 1 or not gui.Parent then
			connection:Disconnect()
			gui:Destroy()
			return
		end
		local frame = math.min(15, math.floor(alpha * 16))
		image.ImageRectOffset = Vector2.new((frame % 4) * 256, math.floor(frame / 4) * 256)
		local eased = 1 - (1 - alpha) ^ 3
		local size = options.size0 + (options.size1 - options.size0) * eased
		gui.Size = UDim2.fromScale(size, size)
	end)
	return gui
end

------------------------------------------------------------------------
-- Particle bursts

local function emitter(parent, props)
	local e = Instance.new("ParticleEmitter")
	e.Enabled = false
	e.Texture = props.texture
	e.Color = ColorSequence.new(props.color or Color3.new(1, 1, 1))
	e.LightEmission = props.lightEmission or 0
	e.LightInfluence = props.lightInfluence or 0
	e.Size = props.size
	e.Transparency = props.transparency or NumberSequence.new(0, 1)
	e.Lifetime = props.lifetime
	e.Speed = props.speed
	e.SpreadAngle = props.spread or Vector2.new(180, 180)
	e.Drag = props.drag or 0
	e.Acceleration = props.acceleration or Vector3.zero
	e.Rotation = props.rotation or NumberRange.new(0, 360)
	e.RotSpeed = props.rotSpeed or NumberRange.new(0)
	e.Orientation = props.orientation or Enum.ParticleOrientation.FacingCamera
	e.EmissionDirection = props.direction or Enum.NormalId.Top
	e.Squash = props.squash or NumberSequence.new(0)
	e.ZOffset = props.zOffset or 0
	if props.flipbook then
		e.FlipbookLayout = Enum.ParticleFlipbookLayout.Grid4x4
		e.FlipbookMode = Enum.ParticleFlipbookMode.OneShot
	end
	e.Parent = parent
	e:Emit(props.count or 1)
	return e
end

local function sparks(parent, count, color, speed)
	emitter(parent, {
		texture = TEX.spark,
		color = color,
		lightEmission = 1,
		size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.32), NumberSequenceKeypoint.new(1, 0) }),
		squash = NumberSequence.new(-1.4),
		transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.7, 0.1), NumberSequenceKeypoint.new(1, 1) }),
		lifetime = NumberRange.new(0.12, 0.32),
		speed = NumberRange.new(speed * 0.55, speed),
		drag = 7,
		acceleration = Vector3.new(0, -40, 0),
		orientation = Enum.ParticleOrientation.VelocityParallel,
		rotation = NumberRange.new(0),
		count = count,
	})
end

local function glow(parent, size, color, lifetime)
	emitter(parent, {
		texture = TEX.glow,
		color = color,
		lightEmission = 1,
		size = NumberSequence.new({ NumberSequenceKeypoint.new(0, size), NumberSequenceKeypoint.new(1, size * 1.6) }),
		transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 1) }),
		lifetime = NumberRange.new(lifetime),
		speed = NumberRange.new(0),
		count = 1,
	})
end

local function smoke(parent, count, size, speed, color)
	emitter(parent, {
		texture = TEX.smoke,
		flipbook = true,
		color = color or Color3.fromRGB(176, 168, 158),
		lightInfluence = 0.6,
		size = NumberSequence.new({ NumberSequenceKeypoint.new(0, size), NumberSequenceKeypoint.new(1, size * 2.2) }),
		transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 1) }),
		lifetime = NumberRange.new(0.55, 0.85),
		speed = NumberRange.new(speed * 0.5, speed),
		drag = 4,
		rotSpeed = NumberRange.new(-40, 40),
		count = count,
	})
end

local function flash(parent, color, brightness, range, duration)
	local light = Instance.new("PointLight")
	light.Color = color
	light.Brightness = brightness
	light.Range = range
	light.Shadows = false
	light.Parent = parent
	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function()
		local alpha = (os.clock() - start) / duration
		if alpha >= 1 or not light.Parent then
			connection:Disconnect()
			light:Destroy()
			return
		end
		light.Brightness = brightness * (1 - alpha) ^ 2
	end)
end

-- Dust thrown outward along the ground.
local function dustRing(position, radius, count, color)
	for i = 1, count do
		local angle = (i / count) * math.pi * 2 + random:NextNumber(-0.2, 0.2)
		local dir = Vector3.new(math.cos(angle), 0.12, math.sin(angle))
		local a = Instance.new("Attachment")
		a.WorldCFrame = CFrame.lookAt(position + dir * 0.6, position + dir * 2)
		a.Parent = workspace.Terrain
		Debris:AddItem(a, 2)
		emitter(a, {
			texture = TEX.smoke,
			flipbook = true,
			color = color or Color3.fromRGB(170, 160, 148),
			lightInfluence = 0.6,
			size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.2), NumberSequenceKeypoint.new(1, 3.4) }),
			transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(1, 1) }),
			lifetime = NumberRange.new(0.5, 0.8),
			speed = NumberRange.new(radius * 0.9, radius * 1.3),
			spread = Vector2.new(8, 8),
			direction = Enum.NormalId.Front,
			drag = 5,
			rotSpeed = NumberRange.new(-30, 30),
			count = 1,
		})
	end
end

-- Ground shockwave: a flat ring plus dust thrown outward.
local function groundBurst(position, radius, color)
	ring(facing(position + Vector3.new(0, 0.2, 0), Vector3.yAxis), color or Color3.fromRGB(240, 232, 220), 1, radius, 0.7, 0.45, 0.25, 28)
	dustRing(position, radius, 12)
end

------------------------------------------------------------------------
-- Body flash: a Highlight over the whole character that fades out fast.
-- The cleanest hit read there is; one is reused per body (Roblox caps the
-- number of active Highlights).

local flashes = setmetatable({}, { __mode = "k" })

function Effects.bodyFlash(model, color, duration, fill)
	if typeof(model) ~= "Instance" or not model.Parent then
		return
	end
	local entry = flashes[model]
	if not entry or not entry.highlight.Parent then
		local highlight = Instance.new("Highlight")
		highlight.Name = "CombatFlash"
		highlight.DepthMode = Enum.HighlightDepthMode.Occluded
		highlight.Adornee = model
		highlight.Enabled = false
		highlight.Parent = model
		entry = { highlight = highlight, token = 0 }
		flashes[model] = entry
	end
	entry.token += 1
	local token = entry.token
	local highlight = entry.highlight
	local fill0 = fill or 0.25
	highlight.FillColor = color
	highlight.OutlineColor = color
	highlight.FillTransparency = fill0
	highlight.OutlineTransparency = 0
	highlight.Enabled = true
	animate(duration, function(alpha)
		if entry.token == token then
			highlight.FillTransparency = fill0 + (1 - fill0) * alpha ^ 0.7
			highlight.OutlineTransparency = alpha ^ 1.6
		end
	end, function()
		if entry.token == token then
			highlight.Enabled = false
		end
	end)
end

------------------------------------------------------------------------
-- Afterimages

local BODY_PARTS = { "Head", "Torso", "Right Arm", "Left Arm", "Right Leg", "Left Leg" }

-- A neon snapshot of the body that fades in place.
function Effects.afterimage(model, color, duration, transparency)
	local ghosts = {}
	for _, name in ipairs(BODY_PARTS) do
		local part = model:FindFirstChild(name)
		if part and part:IsA("BasePart") then
			local ghost = fxPart(color, Enum.Material.Neon)
			ghost.Size = part.Size
			ghost.CFrame = part.CFrame
			ghost.Transparency = transparency
			local mesh = part:FindFirstChildOfClass("SpecialMesh")
			if mesh and mesh.MeshType == Enum.MeshType.Head then
				local copy = Instance.new("SpecialMesh")
				copy.MeshType = Enum.MeshType.Head
				copy.Scale = mesh.Scale
				copy.Parent = ghost
			end
			table.insert(ghosts, ghost)
		end
	end
	animate(duration, function(alpha)
		for _, ghost in ipairs(ghosts) do
			ghost.Transparency = transparency + (1 - transparency) * alpha
		end
	end, function()
		for _, ghost in ipairs(ghosts) do
			ghost:Destroy()
		end
	end)
end

-- A string of afterimages left behind while the body moves.
function Effects.afterimages(model, duration, interval, color, transparency)
	task.spawn(function()
		local stop = os.clock() + duration
		while os.clock() < stop and model.Parent do
			Effects.afterimage(model, color or Color3.fromRGB(210, 225, 255), 0.22, transparency or 0.6)
			task.wait(interval or 0.035)
		end
	end)
end

------------------------------------------------------------------------
-- Movement effects (all clients, for every combatant)

local WIND = Color3.fromRGB(235, 242, 255)

-- Dash: a wind ring punched out behind, dust kicked up, afterimages trail.
function Effects.dash(model, direction, airborne)
	local root = model:FindFirstChild("HumanoidRootPart")
	if not root or not root:IsA("BasePart") then
		return
	end
	direction = (direction * FLAT).Magnitude > 0.01 and (direction * FLAT).Unit or (root.CFrame.LookVector * FLAT).Unit
	local at = anchorAt(root.Position, 1.5)
	Effects.sound("Dash", at, 0.45, 0.7)
	ring(facing(root.Position - direction * 1.2, direction), WIND, 0.8, 4.2, 0.35, 0.28, 0.35, 16)
	streaks(root.Position, -direction, 6, WIND, 3.2, 4, 25, 0.25, 0.08)
	Effects.afterimages(model, Config.RollDuration * 0.85, 0.035)
	if not airborne then
		local ground = groundAt(root.Position, 5)
		if ground then
			local dust = anchorAt(ground + Vector3.new(0, 0.3, 0), 2)
			smoke(dust, 5, 1.1, 9)
		end
	end
end

-- Double jump: a flat wind ring under the feet.
function Effects.doubleJump(model)
	local root = model:FindFirstChild("HumanoidRootPart")
	if not root or not root:IsA("BasePart") then
		return
	end
	local feet = root.Position - Vector3.new(0, 2.8, 0)
	ring(facing(feet, Vector3.yAxis), WIND, 0.6, 4.5, 0.4, 0.32, 0.3, 18)
	streaks(feet, -Vector3.yAxis, 5, WIND, 2.4, 3, 35, 0.22, 0.07)
	Effects.sound("Dash", anchorAt(feet, 1), 0.3, 1.1)
end

-- Landing: dust and a small ground ring scaled by fall speed (0..1).
function Effects.land(position, strength)
	local ground = groundAt(position, 6)
	if not ground then
		return
	end
	local dust = anchorAt(ground + Vector3.new(0, 0.3, 0), 2)
	smoke(dust, math.floor(3 + strength * 6), 0.9 + strength, 4 + strength * 8)
	if strength > 0.5 then
		ring(facing(ground + Vector3.new(0, 0.15, 0), Vector3.yAxis), WIND, 0.8, 3 + strength * 3, 0.3, 0.35, 0.45, 18)
	end
end

-- Footfall puff while sprinting.
function Effects.step(position)
	local ground = groundAt(position, 6)
	if not ground then
		return
	end
	emitter(anchorAt(ground + Vector3.new(0, 0.2, 0), 1.5), {
		texture = TEX.smoke,
		flipbook = true,
		color = Color3.fromRGB(190, 182, 172),
		lightInfluence = 0.6,
		size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.6), NumberSequenceKeypoint.new(1, 1.6) }),
		transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.55), NumberSequenceKeypoint.new(1, 1) }),
		lifetime = NumberRange.new(0.35, 0.55),
		speed = NumberRange.new(1, 3),
		drag = 3,
		count = 1,
	})
end

-- Sent flying: afterimages and a wind trail behind the body.
function Effects.knockback(model, duration)
	Effects.afterimages(model, duration, 0.05, Color3.fromRGB(255, 240, 225), 0.7)
end

------------------------------------------------------------------------
-- Slash skill

local BLOOD = Color3.fromRGB(200, 20, 30)

-- The thrown crescent: a flat blade (decals on both faces) that flies
-- forward, widening slightly, with a red glow riding along.
local function throwCleave(origin, direction)
	local S = Config.Skill
	local part = Instance.new("Part")
	part.Name = "CleaveSlash"
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Transparency = 1
	part.Size = Vector3.new(11, 0.05, 5.5)
	for _, face in ipairs({ Enum.NormalId.Top, Enum.NormalId.Bottom }) do
		local decal = Instance.new("Decal")
		decal.Texture = TEX.cleave
		decal.Face = face
		decal.Parent = part
	end
	local light = Instance.new("PointLight")
	light.Color = BLOOD
	light.Brightness = 3
	light.Range = 12
	light.Parent = part
	local tilt = math.rad(random:NextNumber(-14, 14))
	part.Parent = workspace.Terrain

	local at = anchorAt(origin, 1.5)
	Effects.sound("Swing", at, 0.9, 0.65)
	glow(at, 3, BLOOD, 0.2)

	local duration = S.range / S.speed
	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function()
		local alpha = (os.clock() - start) / duration
		if alpha >= 1 then
			connection:Disconnect()
			part:Destroy()
			return
		end
		local position = origin + direction * (S.range * alpha) + Vector3.new(0, 0.4, 0)
		local scale = 1 + 0.35 * alpha
		part.Size = Vector3.new(11 * scale, 0.05, 5.5 * scale)
		part.CFrame = CFrame.lookAt(position, position + direction) * CFrame.Angles(0, 0, tilt)
		local fade = math.clamp((alpha - 0.75) / 0.25, 0, 1)
		for _, decal in ipairs(part:GetChildren()) do
			if decal:IsA("Decal") then
				decal.Transparency = fade
			end
		end
		light.Brightness = 3 * (1 - fade)
	end)
end

-- One cut landing on a held body: a slash flashes in at a random angle
-- somewhere on them, with a spray of red.
function Effects.dismantleCut(model)
	local root = model:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end
	local offset = Vector3.new(random:NextNumber(-1.3, 1.3), random:NextNumber(-1.8, 1.9), random:NextNumber(-1.3, 1.3))
	local at = anchorAt(root.Position + offset, 1)
	flipbook(at, TEX.dismantle, {
		size0 = random:NextNumber(4.5, 6.5),
		size1 = random:NextNumber(5.5, 7.5),
		duration = random:NextNumber(0.24, 0.34),
		onTop = random:NextNumber() < 0.5,
	})
	if random:NextNumber() < 0.6 then
		sparks(at, 4, BLOOD, 26)
	end
	if random:NextNumber() < 0.45 then
		Effects.sound("Swing", at, 0.35, random:NextNumber(1.5, 1.9))
	end
end

local WARM = Color3.fromRGB(255, 226, 190)
local HOT = Color3.fromRGB(255, 250, 240)
local GOLD = Color3.fromRGB(255, 214, 140)
local STEEL = Color3.fromRGB(190, 215, 255)
local EMBER = Color3.fromRGB(255, 120, 60)

local function hitDirection(position, attacker, defender)
	local a = attacker and attacker:FindFirstChild("HumanoidRootPart")
	local d = defender and defender:FindFirstChild("HumanoidRootPart")
	if a and d then
		local dir = (d.Position - a.Position) * FLAT
		if dir.Magnitude > 0.05 then
			return dir.Unit
		end
	end
	local camera = workspace.CurrentCamera
	return camera and (position - camera.CFrame.Position).Unit or Vector3.zAxis
end

-- Plays an effect and returns how hard it should hit the camera (0..1).
-- `info` is the attack kind for hits (or a direction for dashes).
function Effects.play(kind, position, attacker, defender, info)
	if kind == "CleaveThrow" then
		local root = attacker and attacker:FindFirstChild("HumanoidRootPart")
		local direction = root and (root.CFrame.LookVector * Vector3.new(1, 0, 1)).Unit or Vector3.zAxis
		throwCleave(position, direction)
		return 0.15
	elseif kind == "CleaveHit" then
		local at = anchorAt(position, 2)
		Effects.sound("HeavyHit", at, 0.9, 1.15)
		flipbook(at, TEX.dismantle, { size0 = 7, size1 = 12, duration = 0.32, onTop = true })
		flipbook(at, TEX.parry, { size0 = 3, size1 = 8, duration = 0.3, color = BLOOD, onTop = true })
		sparks(at, 20, BLOOD, 45)
		flash(at, BLOOD, 6, 14, 0.3)
		return 0.45
	end

	local direction = hitDirection(position, attacker, defender)

	if kind == "Hit" then
		-- regular strikes: a white body flash and a small crisp spark, no explosion
		local at = anchorAt(position, 1.5)
		Effects.sound("Hit", at, 0.75)
		Effects.bodyFlash(defender, HOT, 0.16, 0.15)
		burst(position, HOT, 0.3, 1.8, 0.08, 0.2)
		streaks(position, direction, 4, HOT, 1.5, 2.2, 40, 0.12, 0.06)
		sparks(at, 5, WARM, 34)
		return 0.16
	elseif kind == "HeavyHit" then
		local at = anchorAt(position, 2)
		local big = info == "Finisher" or info == "Critical"
		Effects.sound("HeavyHit", at, 0.9, big and 0.85 or 1)
		Effects.bodyFlash(defender, HOT, big and 0.3 or 0.22, 0.05)
		burst(position, HOT, 0.5, big and 4.6 or 3, 0.13, 0.1)
		ring(facing(position, direction), HOT, 0.5, big and 6 or 4, big and 0.35 or 0.25, 0.24, 0.15, 20)
		streaks(position, direction, big and 9 or 6, HOT, big and 3 or 2.2, big and 6 or 4, 45, 0.2, 0.09)
		sparks(at, big and 16 or 10, WARM, 52)
		if big then
			Effects.sound("Hit", at, 0.6, 0.8)
			smoke(at, 3, 1.3, 7)
			flash(at, WARM, 4, 12, 0.2)
			if defender then
				Effects.knockback(defender, 0.35)
			end
		end
		return big and 0.55 or 0.36
	elseif kind == "Block" then
		local at = anchorAt(position, 1.5)
		Effects.sound("Block", at, 0.7, 0.9)
		Effects.bodyFlash(defender, STEEL, 0.14, 0.6)
		burst(position, STEEL, 0.3, 1.5, 0.08, 0.35)
		sparks(at, 6, STEEL, 28)
		return 0.1
	elseif kind == "Parry" then
		local at = anchorAt(position, 1.5)
		Effects.sound("Parry", at, 0.85)
		Effects.bodyFlash(defender, GOLD, 0.26, 0.3)
		Effects.bodyFlash(attacker, GOLD, 0.2, 0.7)
		burst(position, HOT, 0.5, 3.4, 0.12, 0.1)
		ring(facing(position, direction), GOLD, 0.5, 5, 0.3, 0.26, 0.1, 20)
		streaks(position, nil, 10, GOLD, 2.2, 4, 180, 0.2, 0.08)
		sparks(at, 18, GOLD, 60)
		flash(at, GOLD, 5, 14, 0.2)
		return 0.3
	elseif kind == "GuardBreak" then
		local center = position + Vector3.new(0, 0.6, 0)
		local at = anchorAt(center, 2)
		Effects.sound("GuardBreak", at, 0.95)
		Effects.sound("HeavyHit", at, 0.7, 0.85)
		Effects.bodyFlash(defender, EMBER, 0.4, 0.2)
		burst(center, HOT, 0.8, 4.5, 0.16, 0.1)
		ring(facing(center, direction), EMBER, 0.6, 6, 0.4, 0.3, 0.1, 22)
		shards(center, direction, 14, Color3.fromRGB(200, 225, 255))
		sparks(at, 20, EMBER, 56)
		smoke(at, 3, 1.4, 6)
		flash(at, EMBER, 6, 14, 0.26)
		return 0.6
	elseif kind == "Slam" then
		local at = anchorAt(position + Vector3.new(0, 0.5, 0), 2)
		Effects.sound("HeavyHit", at, 0.95, 0.72)
		Effects.bodyFlash(defender, HOT, 0.24, 0.2)
		burst(position + Vector3.new(0, 0.5, 0), HOT, 0.8, 4.5, 0.16, 0.15)
		groundBurst(position, 13)
		crater(position, 5.5, 12)
		sparks(at, 12, WARM, 44)
		return 0.65
	elseif kind == "Feint" then
		local at = anchorAt(position, 1)
		Effects.sound("Feint", at, 0.35, 1.25)
		smoke(at, 2, 0.8, 3, Color3.fromRGB(210, 210, 215))
		return 0
	elseif kind == "Dodge" then
		local at = anchorAt(position, 1)
		smoke(at, 2, 1, 3, Color3.fromRGB(200, 200, 205))
		if defender then
			Effects.afterimage(defender, Color3.fromRGB(210, 225, 255), 0.3, 0.45)
		end
		return 0
	end
	return 0
end

------------------------------------------------------------------------
-- Swing trails, switched on around each strike.

local TRAIL_LIMBS = { "Right Arm", "Left Arm", "Right Leg", "Left Leg" }

function Effects.attachTrails(model)
	local trails = {}
	for _, limbName in ipairs(TRAIL_LIMBS) do
		local limb = model:FindFirstChild(limbName)
		if limb and not limb:FindFirstChild("FistTrail") then
			local a0 = Instance.new("Attachment")
			a0.Name = "FistTrailTop"
			a0.Position = Vector3.new(0, -0.45, 0)
			a0.Parent = limb
			local a1 = Instance.new("Attachment")
			a1.Name = "FistTrailBottom"
			a1.Position = Vector3.new(0, -1.05, 0)
			a1.Parent = limb
			local trail = Instance.new("Trail")
			trail.Name = "FistTrail"
			trail.Attachment0 = a0
			trail.Attachment1 = a1
			trail.Texture = TEX.trail
			trail.TextureMode = Enum.TextureMode.Stretch
			trail.Lifetime = 0.13
			trail.MinLength = 0.05
			trail.LightEmission = 0.7
			trail.FaceCamera = true
			trail.Color = ColorSequence.new(Color3.fromRGB(255, 248, 238))
			trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.4), NumberSequenceKeypoint.new(1, 1) })
			trail.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.2) })
			trail.Enabled = false
			trail.Parent = limb
		end
		local trail = limb and limb:FindFirstChild("FistTrail")
		if trail then
			trails[limbName] = trail
		end
	end
	return trails
end

-- `limbs` defaults to both arms.
function Effects.swingTrails(model, duration, limbs)
	local trails = Effects.attachTrails(model)
	for _, limbName in ipairs(limbs or { "Right Arm", "Left Arm" }) do
		local trail = trails[limbName]
		if trail then
			trail.Enabled = true
			task.delay(duration, function()
				trail.Enabled = false
			end)
		end
	end
end

return Effects
]===]

SOURCES.Motion = [===[
-- Short movement bursts (lunges, dashes, knockback). Runs wherever the
-- character's physics is owned: the client for players, the server for NPCs.

local RunService = game:GetService("RunService")

local FLAT = Vector3.new(1, 0, 1)
local DASH_STEER_RATE = 9
local DASH_MIN_SPEED = 14
local ORBIT_MIN_RADIUS = 7

local Motion = {}

local function getAttachment(root)
	local attachment = root:FindFirstChild("CombatAttachment")
	if not attachment then
		attachment = Instance.new("Attachment")
		attachment.Name = "CombatAttachment"
		attachment.Parent = root
	end
	return attachment
end

local function makePush(root, planeVelocity)
	local push = Instance.new("LinearVelocity")
	push.Name = "CombatPush"
	push.Attachment0 = getAttachment(root)
	push.RelativeTo = Enum.ActuatorRelativeTo.World
	push.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
	push.PrimaryTangentAxis = Vector3.xAxis
	push.SecondaryTangentAxis = Vector3.zAxis
	push.PlaneVelocity = planeVelocity
	push.MaxForce = 1e5
	push.Parent = root
	return push
end

function Motion.stop(root)
	local existing = root:FindFirstChild("CombatPush")
	if existing then
		existing:Destroy()
	end
end

-- Constant push for `duration`, plus an optional vertical launch.
function Motion.push(root, velocity, duration)
	Motion.stop(root)

	local horizontal = Vector2.new(velocity.X, velocity.Z)
	if horizontal.Magnitude > 0.01 and duration > 0 then
		local push = makePush(root, horizontal)
		task.delay(duration, function()
			if push.Parent then
				push:Destroy()
			end
		end)
	end

	if velocity.Y ~= 0 then
		local humanoid = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
		if humanoid and velocity.Y > 0 then
			humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
		end
		local current = root.AssemblyLinearVelocity
		root.AssemblyLinearVelocity = Vector3.new(current.X, velocity.Y, current.Z)
	end
end

-- A burst that starts fast and eases out. While it runs, the movement keys
-- steer it, so a dash can curve around someone instead of locking you into
-- a straight line. With `orbit` (a target's root part) a sideways dash
-- circles the target at roughly its starting distance instead.
function Motion.dash(root, velocity, duration, orbit)
	Motion.stop(root)

	local speed = (velocity * FLAT).Magnitude
	if speed < 0.01 or duration <= 0 then
		return
	end
	local direction = (velocity * FLAT).Unit
	local humanoid = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
	local push = makePush(root, Vector2.new(direction.X, direction.Z) * speed)

	local orbitSign, orbitRadius
	if orbit then
		local offset = (orbit.Position - root.Position) * FLAT
		if offset.Magnitude > 0.5 and math.abs(direction:Dot(offset.Unit)) < 0.65 then
			local tangent = offset.Unit:Cross(Vector3.yAxis)
			orbitSign = direction:Dot(tangent) >= 0 and 1 or -1
			orbitRadius = math.max(offset.Magnitude, ORBIT_MIN_RADIUS)
		end
	end

	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function(dt)
		local alpha = (os.clock() - start) / duration
		if alpha >= 1 or not push.Parent then
			connection:Disconnect()
			if push.Parent then
				push:Destroy()
			end
			return
		end

		local offset = orbitSign and orbit.Parent and (orbit.Position - root.Position) * FLAT
		if offset and offset.Magnitude > 0.5 then
			-- tangent around the target, nudged back toward the orbit radius
			local radial = offset.Unit
			local tangent = radial:Cross(Vector3.yAxis) * orbitSign
			local correction = math.clamp((offset.Magnitude - orbitRadius) * 0.8, -0.6, 0.6)
			direction = (tangent + radial * correction).Unit
		elseif humanoid then
			local move = humanoid.MoveDirection * FLAT
			if move.Magnitude > 0.1 then
				local blended = direction:Lerp(move.Unit, math.min(1, dt * DASH_STEER_RATE))
				if blended.Magnitude > 0.05 then
					direction = blended.Unit
				end
			end
		end

		local current = math.max(DASH_MIN_SPEED, speed * (1 - alpha) ^ 1.6)
		push.PlaneVelocity = Vector2.new(direction.X, direction.Z) * current
	end)
end

------------------------------------------------------------------------
-- Hover: holds a character in the air (slowly sinking) during juggles.
-- `delay` lets a launch carry them up first; each new call refreshes it.

local hoverTokens = setmetatable({}, { __mode = "k" })

function Motion.stopHover(root)
	hoverTokens[root] = (hoverTokens[root] or 0) + 1
	local existing = root:FindFirstChild("CombatHover")
	if existing then
		existing:Destroy()
	end
end

function Motion.hover(root, duration, delay)
	local token = (hoverTokens[root] or 0) + 1
	hoverTokens[root] = token

	local function begin()
		if hoverTokens[root] ~= token or not root.Parent then
			return
		end
		local hover = root:FindFirstChild("CombatHover")
		if not hover then
			hover = Instance.new("LinearVelocity")
			hover.Name = "CombatHover"
			hover.Attachment0 = getAttachment(root)
			hover.RelativeTo = Enum.ActuatorRelativeTo.World
			hover.VelocityConstraintMode = Enum.VelocityConstraintMode.Line
			hover.LineDirection = Vector3.yAxis
			hover.MaxForce = 6e4
			hover.Parent = root
		end
		hover.LineVelocity = -1.5
		task.delay(duration, function()
			if hoverTokens[root] == token and hover.Parent then
				hover:Destroy()
			end
		end)
	end

	if delay and delay > 0 then
		task.delay(delay, begin)
	else
		begin()
	end
end

-- One entry point for the server's Impulse remote. `orbit` is only used by
-- dashes (see Motion.dash).
function Motion.apply(root, kind, velocity, duration, delay, orbit)
	if kind == "push" then
		Motion.push(root, velocity, duration)
	elseif kind == "dash" then
		Motion.dash(root, velocity, duration, orbit)
	elseif kind == "stop" then
		Motion.stop(root)
	elseif kind == "hover" then
		Motion.hover(root, duration, delay)
	elseif kind == "stopHover" then
		Motion.stopHover(root)
	end
end

return Motion
]===]

SOURCES.PoseAnimator = [===[
--[[
	Plays AnimationData directly on a character's joints, with no uploaded
	animation assets. Works the same in Studio and in live servers.

	Every frame the active tracks are layered by priority with fade weights
	and the result is written to Motor6D.Transform (from identity: this owns
	the whole body, locomotion included, so Roblox's default Animate isn't
	used). Tracks mimic the parts of the AnimationTrack API the combat client
	uses: Play, Stop, AdjustSpeed, IsPlaying, GetMarkerReachedSignal.

	On top of the clips sits a procedural layer that makes everything feel
	alive and heavy:
	  - micro-motion and breathing, so nothing is ever perfectly still
	  - overlap: the head and arms lag behind fast torso turns and whip
	    through when the torso stops (follow-through on every strike)
	  - lean into movement and bank into turns
	  - damped springs that impacts kick (PoseAnimator.kick)
	  - hit-stop: PoseAnimator.hitStop freezes a body for a few frames on
	    impact, shuddering in place, so hits land with weight
]]

local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local AnimationData = require(script.Parent.AnimationData)
local AnimationBuilder = require(script.Parent.AnimationBuilder)

local PRIORITY = {
	Core = 0,
	Idle = 1,
	Movement = 2,
	MovementOverlay = 2.5,
	Action = 3,
	Action2 = 4,
	Action3 = 5,
	Action4 = 6,
}

local JOINT_BY_PART = {
	Torso = "Torso",
	Head = "Head",
	["Right Arm"] = "RightArm",
	["Left Arm"] = "LeftArm",
	["Right Leg"] = "RightLeg",
	["Left Leg"] = "LeftLeg",
}

------------------------------------------------------------------------
-- Compiled clips: per joint, a list of { t, cframe, style, direction }

local clips = {}

local function compile(name)
	if clips[name] then
		return clips[name]
	end
	local data = AnimationData[name]
	assert(data, "Unknown animation " .. tostring(name))

	local joints = {}
	for _, key in ipairs(data.keys) do
		for joint in pairs(key.pose) do
			joints[joint] = joints[joint] or {}
		end
	end

	local last = {}
	for _, key in ipairs(data.keys) do
		for joint, list in pairs(joints) do
			last[joint] = key.pose[joint] or last[joint] or { 0, 0, 0 }
			table.insert(list, {
				t = key.t,
				cframe = AnimationBuilder.toTransform(joint, last[joint]),
				style = key.ease or "Linear",
				direction = key.dir or "In",
			})
		end
	end

	local markers = {}
	if data.markers then
		for markerName, time in pairs(data.markers) do
			table.insert(markers, { name = markerName, t = time })
		end
	end

	local priority = data.priority or "Action"
	local clip = {
		name = name,
		joints = joints,
		length = data.length,
		looped = data.looped == true,
		holdLast = data.holdLast == true,
		priority = PRIORITY[priority] or tonumber(priority) or PRIORITY.Action,
		markers = markers,
	}
	clips[name] = clip
	return clip
end

local function ease(alpha, style, direction)
	if style == "Linear" then
		return alpha
	elseif style == "Constant" then
		return 0
	end
	local easingStyle = Enum.EasingStyle[style] or Enum.EasingStyle.Quad
	local easingDirection = Enum.EasingDirection[direction] or Enum.EasingDirection.In
	return TweenService:GetValue(alpha, easingStyle, easingDirection)
end

local function sample(keys, time)
	if time <= keys[1].t then
		return keys[1].cframe
	end
	for i = 1, #keys - 1 do
		local a, b = keys[i], keys[i + 1]
		if time < b.t then
			local alpha = (time - a.t) / (b.t - a.t)
			return a.cframe:Lerp(b.cframe, ease(alpha, a.style, a.direction))
		end
	end
	return keys[#keys].cframe
end

------------------------------------------------------------------------
-- Tracks

local Track = {}
Track.__index = Track

function Track:Play(fadeTime, _weight, speed)
	self.time = 0
	self.firedMarkers = {}
	self.IsPlaying = true
	self.targetWeight = 1
	self.fadeTime = fadeTime or 0.1
	self.speed = speed or 1
	self.order = self.controller:nextOrder()
	if self.fadeTime <= 0 then
		self.weight = 1
	end
	self.controller.active[self] = true
end

function Track:Stop(fadeTime)
	self.IsPlaying = false
	self.targetWeight = 0
	self.fadeTime = fadeTime or 0.1
	if self.fadeTime <= 0 then
		self.weight = 0
	end
end

function Track:AdjustSpeed(speed)
	self.speed = speed
end

function Track:GetMarkerReachedSignal(markerName)
	local track = self
	return {
		Connect = function(_, callback)
			local handlers = track.markerHandlers[markerName]
			if not handlers then
				handlers = {}
				track.markerHandlers[markerName] = handlers
			end
			table.insert(handlers, callback)
			return {
				Disconnect = function()
					local index = table.find(handlers, callback)
					if index then
						table.remove(handlers, index)
					end
				end,
			}
		end,
	}
end

-- `dt` drives the fades (real time); `animDt` drives the clip (frozen
-- during hit-stop).
function Track:step(dt, animDt)
	local clip = self.clip

	if self.weight ~= self.targetWeight then
		local rate = self.fadeTime > 0 and dt / self.fadeTime or 1
		if self.weight < self.targetWeight then
			self.weight = math.min(self.targetWeight, self.weight + rate)
		else
			self.weight = math.max(self.targetWeight, self.weight - rate)
		end
	end

	if not self.IsPlaying and self.weight <= 0 then
		return false
	end

	local previous = self.time
	self.time += animDt * self.speed

	for _, marker in ipairs(clip.markers) do
		if not self.firedMarkers[marker.name] and previous <= marker.t and self.time >= marker.t then
			self.firedMarkers[marker.name] = true
			local handlers = self.IsPlaying and self.markerHandlers[marker.name]
			if handlers then
				for _, handler in ipairs(handlers) do
					task.spawn(handler)
				end
			end
		end
	end

	if self.time >= clip.length then
		if clip.looped then
			self.time %= clip.length
			self.firedMarkers = {}
		elseif clip.holdLast then
			self.time = clip.length
		elseif self.IsPlaying then
			self.time = clip.length
			self:Stop(0.1)
		end
	end
	return true
end

------------------------------------------------------------------------
-- Controllers (one per character)

local Controller = {}
Controller.__index = Controller

local controllers = {}

function Controller:nextOrder()
	self.counter += 1
	return self.counter
end

function Controller:findMotors()
	self.motors = {}
	for _, motor in ipairs(self.model:GetDescendants()) do
		if motor:IsA("Motor6D") and motor.Part1 then
			local joint = JOINT_BY_PART[motor.Part1.Name]
			if joint then
				self.motors[joint] = motor
			end
		end
	end
end

function Controller:track(name)
	local track = self.tracks[name]
	if not track then
		track = setmetatable({
			controller = self,
			clip = compile(name),
			Name = name,
			time = 0,
			weight = 0,
			targetWeight = 0,
			fadeTime = 0.1,
			speed = 1,
			order = 0,
			IsPlaying = false,
			markerHandlers = {},
			firedMarkers = {},
		}, Track)
		self.tracks[name] = track
	end
	return track
end

------------------------------------------------------------------------
-- Procedural layer

local SPRING_STIFFNESS = 260
local SPRING_DAMPING = 17

-- How much each joint lags behind the torso's rotation (overlap).
local DRAG = {
	Head = 0.2,
	RightArm = 0.07,
	LeftArm = 0.07,
}
local MAX_DRAG_KICK = 420

-- Micro-motion: slow noise (degrees) so no joint ever sits perfectly still.
local MICRO = {
	Torso = 0.9,
	Head = 2.6,
	RightArm = 2.4,
	LeftArm = 2.4,
}
local MICRO_SEED = { Torso = 1.7, Head = 5.3, RightArm = 9.1, LeftArm = 13.9 }

local JOINT_ROTATION = {
	Torso = CFrame.fromOrientation(-math.pi / 2, math.pi, 0),
}

function Controller:kick(joint, impulse)
	local spring = self.springs[joint]
	if not spring then
		spring = { pos = Vector3.zero, vel = Vector3.zero }
		self.springs[joint] = spring
	end
	spring.vel += impulse
end

-- Feeds the torso's angular acceleration into head/arm springs so they
-- trail behind turns and overshoot when the torso stops.
function Controller:overlap(torsoTransform, dt)
	if dt <= 0 then
		return
	end
	local previous = self.lastTorso
	self.lastTorso = torsoTransform
	if not previous then
		return
	end

	local axis, angle = (previous:Inverse() * torsoTransform):ToAxisAngle()
	if angle ~= angle or axis.Magnitude < 0.5 then
		return
	end
	-- transform space -> pose space (pitch, yaw, roll axes)
	local omega = JOINT_ROTATION.Torso:VectorToWorldSpace(axis) * math.deg(angle) / dt
	local delta = omega - self.lastOmega
	self.lastOmega = omega
	if delta.Magnitude > 4000 then
		return -- a teleport or a clip switch, not motion
	end

	for joint, gain in pairs(DRAG) do
		local impulse = -delta * gain
		if impulse.Magnitude > MAX_DRAG_KICK then
			impulse = impulse.Unit * MAX_DRAG_KICK
		end
		if impulse.Magnitude > 2 then
			self:kick(joint, impulse)
		end
	end
end

function Controller:procedural(dt, frozen)
	self.clock += dt
	local offsets = {}

	local function add(joint, pitch, yaw, roll, x, y, z)
		local o = offsets[joint]
		if not o then
			o = { 0, 0, 0, 0, 0, 0 }
			offsets[joint] = o
		end
		o[1] += pitch or 0
		o[2] += yaw or 0
		o[3] += roll or 0
		o[4] += x or 0
		o[5] += y or 0
		o[6] += z or 0
	end

	-- micro-motion
	local drift = self.clock * 0.8
	for joint, amount in pairs(MICRO) do
		local seed = MICRO_SEED[joint]
		add(joint,
			math.noise(drift, seed) * amount,
			math.noise(seed, drift) * amount * 0.6,
			math.noise(drift + seed, seed * 0.5) * amount * 0.5)
	end

	-- breathing
	local breath = math.sin(self.clock * math.pi * 2 * 0.3)
	add("Torso", -breath * 0.9, 0, 0, 0, breath * 0.03, 0)
	add("Head", breath * 1.2, 0, 0)
	add("RightArm", breath * 1.6, 0, 0)
	add("LeftArm", breath * 1.6, 0, 0)

	local root = self.model:FindFirstChild("HumanoidRootPart")
	if root and root:IsA("BasePart") then
		-- lean into movement, arms trail a little behind
		local localVel = root.CFrame:VectorToObjectSpace(root.AssemblyLinearVelocity)
		local target = Vector3.new(-localVel.Z, 0, localVel.X)
		self.lean = self.lean:Lerp(target, math.min(1, dt * 8))
		local forward = math.clamp(self.lean.X, -32, 32)
		local side = math.clamp(self.lean.Z, -32, 32)
		add("Torso", -forward * 0.34, 0, side * 0.32)
		add("Head", forward * 0.2, 0, -side * 0.16)
		add("RightArm", -forward * 0.28, 0, 0)
		add("LeftArm", -forward * 0.28, 0, 0)

		-- bank into turns, head leads the turn
		local look = root.CFrame.LookVector
		local heading = math.atan2(-look.X, -look.Z)
		if self.lastHeading and dt > 0 then
			local turn = (heading - self.lastHeading + math.pi) % (2 * math.pi) - math.pi
			local rate = math.deg(turn) / dt
			local speed = Vector2.new(localVel.X, localVel.Z).Magnitude
			local bank = math.clamp(rate * math.clamp(speed / 20, 0.15, 1.3) * 0.03, -14, 14)
			self.bank += (bank - self.bank) * math.min(1, dt * 10)
		end
		self.lastHeading = heading
		add("Torso", 0, 0, self.bank)
		add("Head", 0, self.bank * 0.9, -self.bank * 0.5)
	end

	-- springs
	for joint, spring in pairs(self.springs) do
		local accel = -spring.pos * SPRING_STIFFNESS - spring.vel * SPRING_DAMPING
		spring.vel += accel * dt
		spring.pos += spring.vel * dt
		if spring.pos.Magnitude < 0.01 and spring.vel.Magnitude < 0.1 then
			self.springs[joint] = nil
		else
			add(joint, spring.pos.X, spring.pos.Y, spring.pos.Z)
		end
	end

	-- hit-stop shudder
	if frozen and self.shudder > 0 then
		local s = self.shudder
		add("Torso", 0, 0, 0, (math.random() - 0.5) * s, (math.random() - 0.5) * s * 0.4, (math.random() - 0.5) * s)
	end

	return offsets
end

function Controller:step(dt)
	local now = os.clock()
	local frozen = now < self.frozenUntil
	local animDt = frozen and 0 or dt

	local layers = {}
	for track in pairs(self.active) do
		if track:step(dt, animDt) then
			table.insert(layers, track)
		else
			self.active[track] = nil
		end
	end

	table.sort(layers, function(a, b)
		if a.clip.priority ~= b.clip.priority then
			return a.clip.priority < b.clip.priority
		end
		return a.order < b.order
	end)

	local humanoid = self.model:FindFirstChildOfClass("Humanoid")
	local alive = humanoid ~= nil and humanoid.Health > 0

	local results = {}
	for joint in pairs(self.motors) do
		local result = CFrame.identity
		for _, track in ipairs(layers) do
			local keys = track.clip.joints[joint]
			if keys and track.weight > 0 then
				result = result:Lerp(sample(keys, track.time), track.weight)
			end
		end
		results[joint] = result
	end

	if alive and results.Torso then
		self:overlap(results.Torso, animDt)
	end
	local offsets = alive and self:procedural(dt, frozen) or {}

	for joint, motor in pairs(self.motors) do
		if motor.Parent then
			local result = results[joint]
			local offset = offsets[joint]
			if offset then
				result = result * AnimationBuilder.toTransform(joint, offset)
			end
			motor.Transform = result
		end
	end
end

local PoseAnimator = {}

-- Adds a physical jolt to a joint: impulse is degrees/second as
-- Vector3(pitch, yaw, roll) in the same convention as AnimationData.
function PoseAnimator.kick(model, joint, impulse)
	PoseAnimator.get(model):kick(joint, impulse)
end

-- Freezes the body's clips for `duration` seconds (springs keep moving) and
-- shudders it by `shudder` studs. Re-freezing extends, never shortens.
function PoseAnimator.hitStop(model, duration, shudder)
	local controller = PoseAnimator.get(model)
	local untilTime = os.clock() + duration
	if untilTime > controller.frozenUntil then
		controller.frozenUntil = untilTime
	end
	controller.shudder = shudder or 0
end

function PoseAnimator.get(model)
	local controller = controllers[model]
	if controller then
		return controller
	end
	controller = setmetatable({
		model = model,
		tracks = {},
		active = {},
		motors = {},
		counter = 0,
		springs = {},
		clock = math.random() * 10,
		lean = Vector3.zero,
		bank = 0,
		lastHeading = nil,
		lastTorso = nil,
		lastOmega = Vector3.zero,
		frozenUntil = 0,
		shudder = 0,
	}, Controller)
	controller:findMotors()
	controllers[model] = controller

	model.DescendantAdded:Connect(function(descendant)
		if descendant:IsA("Motor6D") then
			controller:findMotors()
		end
	end)
	model.Destroying:Once(function()
		controllers[model] = nil
	end)
	return controller
end

-- PreSimulation runs after Roblox's Animator has written this frame's
-- transforms, so these poses always win.
RunService.PreSimulation:Connect(function(dt)
	for model, controller in pairs(controllers) do
		if model.Parent then
			controller:step(dt)
		end
	end
end)

return PoseAnimator
]===]

SOURCES.CombatService = [===[
--[[
	Server-authoritative combat. Every character that can fight (players and
	dummies) is a combatant with one state machine:

	  Idle, Attacking, Blocking, Rolling, Stunned, Parried, GuardBroken

	Juggling is tracked alongside the state: a juggled combatant floats
	(Motion.hover) for a short time after each air hit and is released if
	they block or dash out, the juggle times out, or they get slammed.

	The client only sends inputs. Timing, hit detection, damage, posture and
	parry resolution all happen here. Effects carry the attack kind so every
	client can scale its hit effects, hit-stop and camera kick to the move.
]]

local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local CombatShared = ReplicatedStorage.Combat
local Config = require(CombatShared.Config)
local AnimationData = require(CombatShared.AnimationData)
local Motion = require(CombatShared.Motion)
local Remotes = CombatShared.Remotes

local FLAT = Vector3.new(1, 0, 1)

local CombatService = {}

local combatants = {}
CombatService.Combatants = combatants

local attackStarted = Instance.new("BindableEvent")
-- (attacker, attackKind, hitTime) - lets dummies react to incoming attacks
CombatService.AttackStarted = attackStarted.Event

local now = os.clock

local function flat(vector)
	return vector * FLAT
end

------------------------------------------------------------------------
-- Replication helpers

local function playAnim(c, name, predicted, stop)
	if c.player and predicted then
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= c.player then
				Remotes.Anim:FireClient(player, c.model, name, stop)
			end
		end
	else
		Remotes.Anim:FireAllClients(c.model, name, stop)
	end
end

local function stopAnim(c, name, predicted)
	playAnim(c, name, predicted, true)
end

-- `info` is the attack kind for hits, or the direction for a dash.
local function effect(kind, position, attacker, defender, info)
	Remotes.Effect:FireAllClients(kind, position, attacker and attacker.model, defender and defender.model, info)
end

-- Movement runs where the character's physics lives: the owning client for
-- players, the server for dummies.
local function motion(c, kind, velocity, duration, delay)
	if c.player then
		Remotes.Impulse:FireClient(c.player, kind, velocity or Vector3.zero, duration or 0, delay or 0)
	else
		Motion.apply(c.root, kind, velocity or Vector3.zero, duration or 0, delay or 0)
	end
end

local function push(c, velocity, duration)
	motion(c, "push", velocity, duration)
end

local function dash(c, velocity, duration)
	motion(c, "dash", velocity, duration)
end

local function isAirborne(c)
	return c.humanoid.FloorMaterial == Enum.Material.Air
end

local function stopMotion(c)
	motion(c, "stop")
end

local function hover(c, duration, delay)
	motion(c, "hover", nil, duration, delay)
end

local function stopHover(c)
	motion(c, "stopHover")
end

------------------------------------------------------------------------
-- State

local function walkSpeedFor(c)
	local state = c.state
	if state == "Idle" then
		return c.sprinting and Config.SprintSpeed or Config.WalkSpeed
	elseif state == "Blocking" then
		return Config.BlockWalkSpeed
	elseif state == "Attacking" then
		return Config.AttackWalkSpeed
	elseif state == "Rolling" then
		return Config.WalkSpeed
	elseif state == "GuardBroken" or state == "Captured" or state == "Kneeling" then
		return 0
	end
	return Config.StunWalkSpeed
end

local function applyMovement(c)
	c.humanoid.WalkSpeed = walkSpeedFor(c)
	c.humanoid.JumpHeight = (c.state == "Idle") and Config.JumpHeight or 0
end

local function setState(c, state, duration)
	c.state = state
	c.token += 1
	c.model:SetAttribute("CombatState", state)
	applyMovement(c)

	if duration then
		local token = c.token
		task.delay(duration, function()
			if c.token == token then
				setState(c, "Idle")
			end
		end)
	end
	return c.token
end

local function setPosture(c, value)
	c.posture = math.clamp(value, 0, c.maxPosture)
	c.model:SetAttribute("Posture", math.floor(c.posture + 0.5))
end

local function isFacing(defender, attacker)
	local toAttacker = flat(attacker.root.Position - defender.root.Position)
	if toAttacker.Magnitude < 0.05 then
		return true
	end
	local look = flat(defender.root.CFrame.LookVector)
	return look.Unit:Dot(toAttacker.Unit) >= Config.FacingDot
end

local function isAlive(c)
	return c.humanoid.Health > 0
end

local function isJuggled(c, t)
	return c.juggledBy ~= nil and (t or now()) < c.juggleUntil
end

local function releaseJuggle(c)
	if c.juggledBy then
		c.juggledBy = nil
		c.juggleUntil = 0
		c.model:SetAttribute("Juggled", false)
		stopHover(c)
	end
end

-- Is `c` currently keeping someone airborne?
local function juggleTargetOf(c, t)
	for _, other in pairs(combatants) do
		if other.juggledBy == c and isJuggled(other, t)
			and (other.root.Position - c.root.Position).Magnitude < 12 then
			return other
		end
	end
	return nil
end

local function groundBelow(c)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ignore = {}
	for model in pairs(combatants) do
		table.insert(ignore, model)
	end
	params.FilterDescendantsInstances = ignore
	local result = workspace:Raycast(c.root.Position, Vector3.new(0, -60, 0), params)
	return result and result.Position or (c.root.Position - Vector3.new(0, 3, 0))
end

-- Returns true if the hit killed the target. Death is Roblox's normal death.
local function damage(c, amount)
	if amount <= 0 or not isAlive(c) then
		return false
	end
	c.lastDamaged = now()
	c.humanoid.Health = math.max(0, c.humanoid.Health - amount)
	if not isAlive(c) then
		c.attack = nil
		c.token += 1
		return true
	end
	return false
end

------------------------------------------------------------------------
-- Hits

local overlap = OverlapParams.new()
overlap.FilterType = Enum.RaycastFilterType.Include

local function findTarget(c, attack)
	local candidates = {}
	for model, other in pairs(combatants) do
		if other ~= c and isAlive(other) then
			table.insert(candidates, model)
		end
	end
	if #candidates == 0 then
		return nil
	end
	overlap.FilterDescendantsInstances = candidates

	local height = attack.height or 6
	local boxCFrame = CFrame.lookAlong(c.root.Position, flat(c.root.CFrame.LookVector).Unit)
		* CFrame.new(0, attack.height and -1.5 or 0, -attack.range / 2)
	local parts = workspace:GetPartBoundsInBox(boxCFrame, Vector3.new(attack.width, height, attack.range), overlap)

	local best, bestDistance
	for _, part in ipairs(parts) do
		local other = combatants[part.Parent]
		if other and other ~= c then
			local distance = (other.root.Position - c.root.Position).Magnitude
			if not bestDistance or distance < bestDistance then
				best, bestDistance = other, distance
			end
		end
	end
	return best
end

local function guardBreak(defender, attacker, attack, kind)
	defender.attack = nil
	defender.combo = 0
	defender.blockReadyAt = now() + Config.GuardBreakStun + Config.BlockCooldown
	releaseJuggle(defender)
	setPosture(defender, 0)
	effect("GuardBreak", defender.root.Position, attacker, defender, kind)
	if damage(defender, attack.damage * Config.GuardBreakDamageMult) then
		return
	end
	setState(defender, "GuardBroken", Config.GuardBreakStun)
	playAnim(defender, "GuardBreak")
	push(defender, flat(attacker.root.CFrame.LookVector) * 14, 0.15)
end

local function resolveHit(attacker, defender, attack, kind)
	local t = now()
	if not isAlive(defender) or t < defender.invincibleUntil then
		return
	end
	-- Held by the slash skill: extra hits still hurt but don't break the hold.
	if defender.state == "Captured" then
		effect("Hit", defender.root.Position + Vector3.new(0, 0.6, 0), attacker, defender)
		damage(defender, attack.damage)
		return
	end
	if t < defender.iframesUntil then
		effect("Dodge", defender.root.Position, attacker, defender)
		return
	end

	local contact = defender.root.Position:Lerp(attacker.root.Position, 0.4) + Vector3.new(0, 0.6, 0)
	local facing = isFacing(defender, attacker)
	local stunnable = defender.state ~= "Stunned" and defender.state ~= "GuardBroken" and defender.state ~= "Parried"

	-- Parry: negates everything, refunds the parry, recovers posture, recoils the attacker.
	if facing and t <= defender.parryUntil and stunnable then
		defender.parryUntil = 0
		defender.parryReadyAt = 0
		setPosture(defender, defender.posture - Config.ParryPostureRecover)

		attacker.attack = nil
		attacker.combo = 0
		-- Can't attack again for a moment, but can still parry the counter:
		-- that's what makes parry trading possible.
		attacker.nextActionAt = t + Config.ParriedStun
		setState(attacker, "Parried", Config.ParriedStun)
		stopMotion(attacker)
		playAnim(attacker, "Parried")
		playAnim(defender, "BlockImpact")
		effect("Parry", contact, attacker, defender, kind)
		if not isJuggled(defender, t) then
			stopHover(attacker)
		end
		return
	end

	-- Block: chip damage and posture. Overflowing posture guard breaks.
	if facing and defender.state == "Blocking" then
		local shaky = t - defender.blockStart < Config.ShakyBlockTime
		local postureDamage = attack.posture * (shaky and Config.ShakyPostureMult or 1)
		defender.lastPostureGain = t

		if defender.posture + postureDamage >= defender.maxPosture then
			guardBreak(defender, attacker, attack, kind)
			return
		end

		setPosture(defender, defender.posture + postureDamage)
		effect("Block", contact, attacker, defender, kind)
		playAnim(defender, "BlockImpact")
		push(defender, flat(attacker.root.CFrame.LookVector) * 2.5, 0.08)
		damage(defender, attack.damage * Config.ChipDamage)
		return
	end

	-- Clean hit: damage, interrupt, hitstun, knockback.
	local heavy = attack.heavy or attack.knockback >= 18 or attack.launcher or attack.slam
	effect(heavy and "HeavyHit" or "Hit", contact, attacker, defender, kind)
	if damage(defender, attack.damage) then
		releaseJuggle(defender)
		return
	end

	-- A guard-broken target takes free hits without its stun being shortened.
	if defender.state == "GuardBroken" and not attack.launcher and not attack.slam then
		push(defender, flat(attacker.root.CFrame.LookVector) * 2, 0.1)
		return
	end

	defender.attack = nil
	defender.combo = 0
	defender.sprinting = false
	if defender.state == "Rolling" then
		stopMotion(defender)
	end

	local direction = flat(attacker.root.CFrame.LookVector)

	if attack.slam then
		-- Spiked into the ground: long stun, ground impact where they land.
		releaseJuggle(defender)
		setState(defender, "Stunned", Config.SlamStun)
		playAnim(defender, "Slammed")
		local ground = groundBelow(defender)
		local fall = math.max(0, defender.root.Position.Y - ground.Y - 3)
		push(defender, direction * attack.knockback + Vector3.new(0, -Config.SlamSpeed, 0), 0.12)
		task.delay(math.min(0.35, fall / Config.SlamSpeed), function()
			effect("Slam", groundBelow(defender), attacker, defender, kind)
		end)
		return
	end

	setState(defender, "Stunned", attack.hitstun)
	local react
	if attack.react == "Knockback" then
		react = "Knockback"
	elseif not facing then
		react = "HitBack"
	else
		react = attack.react or "HitFront"
	end
	playAnim(defender, react)

	if attack.juggle then
		-- Launch (or keep) them in the air for a follow-up.
		local first = not isJuggled(defender, t)
		if first then
			defender.juggleStart = t
		end
		if t - defender.juggleStart < Config.MaxJuggleTime then
			defender.juggledBy = attacker
			defender.juggleUntil = t + Config.JuggleHover + (attack.launcher and Config.LaunchApexDelay or 0)
			defender.model:SetAttribute("Juggled", true)
			local apex = attack.launcher and Config.LaunchApexDelay or 0
			push(defender, direction * attack.knockback + Vector3.new(0, attack.launch or 0, 0), 0.12)
			hover(defender, Config.JuggleHover, apex)
			if attack.selfLaunch then
				push(attacker, Vector3.new(0, attack.selfLaunch, 0), 0)
				hover(attacker, Config.AirAttackHover, apex)
			end
			return
		end
		releaseJuggle(defender)
	end

	push(defender, direction * attack.knockback + Vector3.new(0, attack.launch or 0, 0), attack.pushTime or 0.15)
end

local function startAttack(c, kind, predicted)
	local attack = Config.Attacks[kind]
	local anim = AnimationData[attack.anim]
	local hitDelay = anim.markers.Hit
	local t = now()

	local token = setState(c, "Attacking")
	c.attack = { kind = kind, def = attack, started = t, hitAt = t + hitDelay }
	c.nextActionAt = t + anim.recover

	playAnim(c, attack.anim, predicted)
	attackStarted:Fire(c, kind, c.attack.hitAt)

	-- Stay up with the target while air comboing; a slam drops you with them.
	if attack.air and not attack.slam and juggleTargetOf(c, t) then
		hover(c, Config.AirAttackHover)
	elseif attack.slam then
		stopHover(c)
	end

	if attack.lunge and not attack.lungeAtHit then
		push(c, flat(c.root.CFrame.LookVector) * attack.lunge[1], attack.lunge[2])
	end

	task.delay(hitDelay, function()
		if c.token ~= token then
			return
		end
		if attack.lunge and attack.lungeAtHit then
			push(c, flat(c.root.CFrame.LookVector) * attack.lunge[1], attack.lunge[2])
		end

		local target = findTarget(c, attack)
		if target then
			resolveHit(c, target, attack, kind)
		end
		if c.token ~= token then
			return
		end

		task.delay(anim.recover - hitDelay, function()
			if c.token == token then
				c.attack = nil
				setState(c, "Idle")
			end
		end)
	end)
end

------------------------------------------------------------------------
-- Actions. Each returns (accepted, animationName).

local function canStartAction(c, t)
	return c.state == "Idle" and t >= c.nextActionAt and t > c.parryUntil
end

-- After your hit frame you can cancel the rest of the swing into a block,
-- parry or dash, so one attack doesn't lock you out of everything else.
local function inRecovery(c, t)
	return c.state == "Attacking" and c.attack ~= nil and t > c.attack.hitAt
end

local function cancelRecovery(c, t)
	c.attack = nil
	c.nextActionAt = t
end

function CombatService.m1(c, options, predicted)
	local t = now()
	if not canStartAction(c, t) then
		return false
	end

	if t - c.lastM1 > Config.ComboResetTime then
		c.combo = 0
	end

	local airborne = options.airborne or c.humanoid.FloorMaterial == Enum.Material.Air
	local speed = flat(c.root.AssemblyLinearVelocity).Magnitude

	local kind
	if airborne then
		-- In the air: keep juggling, and the last hit (or a lone jump attack) slams.
		if juggleTargetOf(c, t) and c.combo + 1 < Config.ComboLength then
			kind = Config.AirChain[c.combo % #Config.AirChain + 1]
		else
			kind = "Downslam"
		end
	elseif options.launcher then
		kind = "Uppercut"
	elseif c.sprinting and speed > Config.WalkSpeed + 2 then
		kind = "RunningAttack"
	elseif c.combo + 1 >= Config.ComboLength then
		kind = "Finisher"
	else
		kind = Config.M1Chain[c.combo % #Config.M1Chain + 1]
	end

	c.combo += 1
	if Config.Attacks[kind].endsCombo then
		c.combo = 0
	end
	c.lastM1 = t
	c.sprinting = false
	c.model:SetAttribute("Combo", c.combo)
	c.model:SetAttribute("ComboExpires", workspace:GetServerTimeNow() + Config.ComboResetTime)

	startAttack(c, kind, predicted)
	return true, Config.Attacks[kind].anim
end

function CombatService.critical(c, predicted)
	local t = now()
	if not canStartAction(c, t) or t < c.critReadyAt then
		return false
	end
	c.critReadyAt = t + Config.Attacks.Critical.cooldown
	c.sprinting = false
	startAttack(c, "Critical", predicted)
	return true, "Critical"
end

function CombatService.feint(c, predicted)
	local t = now()

	if c.state == "Attacking" and c.attack then
		if not c.attack.def.feintable or t < c.feintReadyAt or t > c.attack.hitAt - Config.FeintLockout then
			return false
		end
		c.feintReadyAt = t + Config.FeintCooldown
		c.attack = nil
		c.nextActionAt = t + 0.1
		setState(c, "Idle")
		stopMotion(c)
		playAnim(c, "Feint", predicted)
		effect("Feint", c.root.Position, c)
		return true, "Feint"
	end

	if c.state == "Rolling" and t - c.rollStarted <= Config.RollCancelWindow then
		c.iframesUntil = 0
		c.rollReadyAt = t + Config.RollCancelCooldown
		setState(c, "Idle")
		stopMotion(c)
		playAnim(c, "Feint", predicted)
		return true, "Feint"
	end

	return false
end

function CombatService.blockDown(c, resume, predicted)
	local t = now()
	if t < c.blockReadyAt then
		return false
	end
	if c.state == "Rolling" then
		c.iframesUntil = 0
	elseif inRecovery(c, t) then
		cancelRecovery(c, t)
	elseif c.state ~= "Idle" and c.state ~= "Parried" then
		return false
	end

	-- Guarding mid-juggle is how you get out of an air combo.
	if isJuggled(c, t) then
		releaseJuggle(c)
	end

	-- Pressing F opens the parry window; keeping it held is a normal block.
	-- Both use the same block pose, so a parry is purely about timing.
	if not resume and t >= c.parryReadyAt then
		c.parryUntil = t + Config.ParryWindow
		c.parryReadyAt = t + Config.ParryCooldown
	end

	c.sprinting = false
	c.blockStart = t
	setState(c, "Blocking")
	playAnim(c, "Block", predicted)
	return true, "Block"
end

function CombatService.blockUp(c, predicted)
	if c.state == "Blocking" then
		c.blockReadyAt = now() + Config.BlockCooldown
		setState(c, "Idle")
		stopAnim(c, "Block", predicted)
	end
	return true
end

-- Picks the dash clip from the dash direction relative to facing.
function CombatService.dashAnim(root, direction, airborne)
	if airborne then
		return "DashAir"
	end
	local relative = root.CFrame:VectorToObjectSpace(direction)
	if relative.Z < -0.5 then
		return "DashForward"
	elseif relative.Z > 0.5 then
		return "DashBack"
	elseif relative.X < 0 then
		return "DashLeft"
	end
	return "DashRight"
end

function CombatService.roll(c, direction, predicted, airborne)
	local t = now()
	if t < c.rollReadyAt then
		return false
	end
	if inRecovery(c, t) then
		cancelRecovery(c, t)
	elseif c.state ~= "Idle" and c.state ~= "Blocking" then
		return false
	end

	local look = flat(c.root.CFrame.LookVector).Unit
	local move = typeof(direction) == "Vector3" and flat(direction) or Vector3.zero
	local dir = move.Magnitude > 0.1 and move.Unit or look

	-- Players' physics runs on their client, so its grounded check is the
	-- accurate one; dummies are simulated here.
	if c.player then
		airborne = airborne == true
	else
		airborne = isAirborne(c)
	end
	local anim = CombatService.dashAnim(c.root, dir, airborne)

	c.rollReadyAt = t + Config.RollCooldown
	c.iframesUntil = t + Config.RollIFrames
	c.rollStarted = t
	c.sprinting = false
	if c.state == "Blocking" then
		c.blockReadyAt = t + Config.BlockCooldown
	end
	releaseJuggle(c)
	if not juggleTargetOf(c, t) then
		stopHover(c)
	end
	setState(c, "Rolling", Config.RollDuration)
	playAnim(c, anim, predicted)
	dash(c, dir * (airborne and Config.AirDashSpeed or Config.RollSpeed), Config.RollDuration * 0.9)
	if airborne then
		hover(c, Config.RollDuration * 0.9)
	end
	effect("Dash", c.root.Position, c, nil, dir)
	return true, anim
end

-- Second jump in the air. The jump itself is physics on the owning client;
-- this only validates it and shows the flip to everyone else.
function CombatService.doubleJump(c, predicted)
	local t = now()
	if c.state ~= "Idle" or t < c.doubleJumpReadyAt then
		return false
	end
	c.doubleJumpReadyAt = t + 0.35
	playAnim(c, "DoubleJump", predicted)
	effect("DoubleJump", c.root.Position, c)
	return true, "DoubleJump"
end

function CombatService.setSprint(c, on)
	c.sprinting = on == true and c.state == "Idle"
	applyMovement(c)
	return true
end

------------------------------------------------------------------------
-- Slash skill

local function capture(victim, caster)
	local S = Config.Skill
	local t = now()
	victim.attack = nil
	victim.combo = 0
	victim.sprinting = false
	releaseJuggle(victim)
	stopMotion(victim)
	setState(victim, "Captured")
	victim.captureId += 1
	local id = victim.captureId
	victim.model:SetAttribute("Dismantled", true)
	playAnim(victim, "Captured")
	effect("CleaveHit", victim.root.Position + Vector3.new(0, 0.5, 0), caster, victim)

	task.spawn(function()
		local perTick = victim.humanoid.MaxHealth * S.damagePerSecond * S.tickInterval
		local elapsed = 0
		while elapsed < S.captureTime do
			task.wait(S.tickInterval)
			elapsed += S.tickInterval
			if victim.captureId ~= id or not isAlive(victim) or victim.state ~= "Captured" then
				break
			end
			damage(victim, perTick)
		end
		if victim.captureId ~= id then
			return
		end
		victim.model:SetAttribute("Dismantled", false)
		stopAnim(victim, "Captured")
		if isAlive(victim) then
			victim.invincibleUntil = now() + S.kneelTime
			setState(victim, "Kneeling", S.kneelTime)
			playAnim(victim, "Kneel")
		end
	end)
	return t
end

function CombatService.skill(c, predicted)
	local S = Config.Skill
	local t = now()
	if not canStartAction(c, t) or t < c.skillReadyAt then
		return false
	end
	c.skillReadyAt = t + S.cooldown
	c.sprinting = false

	local token = setState(c, "Attacking")
	c.attack = { kind = "Skill", def = { feintable = false }, started = t, hitAt = t + S.release }
	c.nextActionAt = t + S.castTime
	playAnim(c, "SkillCast", predicted)

	task.delay(S.release, function()
		if c.token ~= token or not isAlive(c) then
			return
		end
		local direction = flat(c.root.CFrame.LookVector).Unit
		local origin = c.root.Position + direction * 1.5
		effect("CleaveThrow", origin, c)

		-- the slash travels; the first fighter it passes through is caught
		local start = now()
		local travelled = 0
		while travelled < S.range do
			local step = math.min(S.range, S.speed * (now() - start))
			local segment = math.max(step - travelled, 1)
			local centre = origin + direction * (travelled + segment / 2)
			local candidates = {}
			for model, other in pairs(combatants) do
				if other ~= c and isAlive(other) then
					table.insert(candidates, model)
				end
			end
			overlap.FilterDescendantsInstances = candidates
			local box = CFrame.lookAlong(centre, direction)
			local parts = workspace:GetPartBoundsInBox(box, Vector3.new(S.width, 6, segment + 1), overlap)
			for _, part in ipairs(parts) do
				local victim = combatants[part.Parent]
				if victim and victim ~= c and isAlive(victim) then
					local tt = now()
					if tt < victim.iframesUntil then
						effect("Dodge", victim.root.Position, c, victim)
					elseif tt >= victim.invincibleUntil and victim.state ~= "Captured" then
						capture(victim, c)
						return
					end
				end
			end
			travelled = step
			task.wait()
		end
	end)

	task.delay(S.castTime, function()
		if c.token == token then
			c.attack = nil
			setState(c, "Idle")
		end
	end)
	return true, "SkillCast"
end

------------------------------------------------------------------------
-- Registration

function CombatService.get(model)
	return combatants[model]
end

function CombatService.register(model, player)
	local humanoid = model:WaitForChild("Humanoid")
	local root = model:WaitForChild("HumanoidRootPart")

	humanoid.MaxHealth = Config.MaxHealth
	humanoid.Health = Config.MaxHealth
	humanoid.UseJumpPower = false
	humanoid.JumpHeight = Config.JumpHeight
	-- Plain Roblox overhead health while the custom HUD is out.
	humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.DisplayWhenDamaged
	humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer

	if not root:FindFirstChild("CombatAttachment") then
		local attachment = Instance.new("Attachment")
		attachment.Name = "CombatAttachment"
		attachment.Parent = root
	end

	local c = {
		model = model,
		humanoid = humanoid,
		root = root,
		player = player,

		state = "Idle",
		token = 0,
		attack = nil,

		combo = 0,
		lastM1 = 0,
		nextActionAt = 0,
		critReadyAt = 0,
		feintReadyAt = 0,

		parryUntil = 0,
		parryReadyAt = 0,
		blockStart = 0,
		blockReadyAt = 0,

		juggledBy = nil,
		juggleUntil = 0,
		juggleStart = 0,

		skillReadyAt = 0,
		captureId = 0,
		invincibleUntil = 0,

		rollReadyAt = 0,
		rollStarted = 0,
		iframesUntil = 0,
		doubleJumpReadyAt = 0,

		posture = 0,
		maxPosture = Config.MaxPosture,
		lastPostureGain = 0,
		lastDamaged = 0,

		sprinting = false,
	}

	combatants[model] = c
	setState(c, "Idle")
	setPosture(c, 0)
	CollectionService:AddTag(model, "Combatant")

	local function unregister()
		if combatants[model] == c then
			combatants[model] = nil
			c.token += 1
		end
	end
	model.AncestryChanged:Connect(function(_, parent)
		if not parent then
			unregister()
		end
	end)
	humanoid.Died:Connect(unregister)

	return c
end

RunService.Heartbeat:Connect(function(dt)
	local t = now()
	for _, c in pairs(combatants) do
		if c.juggledBy and t >= c.juggleUntil then
			releaseJuggle(c)
		end
		if c.posture > 0 and c.state ~= "Blocking" and not c.sprinting and t - c.lastPostureGain > Config.PostureRegenDelay then
			setPosture(c, c.posture - Config.PostureRegenRate * dt)
		end
	end
end)

return CombatService
]===]

SOURCES.CombatServer = [===[
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local CombatService = require(script.Parent.CombatService)
local Remotes = ReplicatedStorage.Combat.Remotes

local RESPAWN_DELAY = 3
local MAX_ACTIONS_PER_SECOND = 24

-- Players spawn as R6 with their own avatar.
Players.CharacterAutoLoads = false

local function getSpawnCFrame()
	local spawn = workspace:FindFirstChildOfClass("SpawnLocation")
	if spawn then
		return spawn.CFrame + Vector3.new(0, spawn.Size.Y / 2 + 3, 0)
	end
	return CFrame.new(0, 5, 0)
end

local function spawnCharacter(player)
	local ok, description = pcall(function()
		return Players:GetHumanoidDescriptionFromUserId(math.max(player.UserId, 1))
	end)
	if not ok then
		description = Instance.new("HumanoidDescription")
	end

	local character = Players:CreateHumanoidModelFromDescription(description, Enum.HumanoidRigType.R6)
	character.Name = player.Name
	-- PoseAnimator animates everything (idle, walk, run, jump, fall), so
	-- Roblox's default animations would only fight it.
	local animate = character:FindFirstChild("Animate")
	if animate then
		animate:Destroy()
	end
	character:PivotTo(getSpawnCFrame())
	character.Parent = workspace
	player.Character = character

	character:WaitForChild("Humanoid").Died:Connect(function()
		task.wait(RESPAWN_DELAY)
		if player.Parent then
			character:Destroy()
			spawnCharacter(player)
		end
	end)
end

local function onPlayerAdded(player)
	player.CharacterAdded:Connect(function(character)
		CombatService.register(character, player)
	end)
	spawnCharacter(player)
end

Players.PlayerAdded:Connect(onPlayerAdded)
for _, player in ipairs(Players:GetPlayers()) do
	task.spawn(onPlayerAdded, player)
end

------------------------------------------------------------------------
-- Input

local budgets = {}

local function withinBudget(player)
	local t = os.clock()
	local budget = budgets[player]
	if not budget or t - budget.start >= 1 then
		budget = { start = t, count = 0 }
		budgets[player] = budget
	end
	budget.count += 1
	return budget.count <= MAX_ACTIONS_PER_SECOND
end

Players.PlayerRemoving:Connect(function(player)
	budgets[player] = nil
end)

local handlers = {
	M1 = function(c, arg)
		local options = type(arg) == "table" and arg or {}
		return CombatService.m1(c, {
			launcher = options.launcher == true,
			airborne = options.airborne == true,
		}, true)
	end,
	Critical = function(c)
		return CombatService.critical(c, true)
	end,
	Skill = function(c)
		return CombatService.skill(c, true)
	end,
	Feint = function(c)
		return CombatService.feint(c, true)
	end,
	BlockDown = function(c, arg)
		return CombatService.blockDown(c, arg == true, true)
	end,
	BlockUp = function(c)
		return CombatService.blockUp(c, true)
	end,
	Roll = function(c, arg)
		local options = type(arg) == "table" and arg or {}
		local direction = typeof(options.direction) == "Vector3" and options.direction or nil
		return CombatService.roll(c, direction, true, options.airborne == true)
	end,
	DoubleJump = function(c)
		return CombatService.doubleJump(c, true)
	end,
	Sprint = function(c, arg)
		return CombatService.setSprint(c, arg == true)
	end,
}

Remotes.Action.OnServerEvent:Connect(function(player, action, sequence, arg)
	local handler = type(action) == "string" and handlers[action]
	if not handler or not withinBudget(player) then
		return
	end

	local c = player.Character and CombatService.get(player.Character)
	if not c then
		return
	end

	local accepted, anim = handler(c, arg)
	if type(sequence) == "number" then
		Remotes.Ack:FireClient(player, sequence, accepted == true, anim)
	end
end)
]===]

SOURCES.CombatClient = [===[
--[[
	Client side of the fist combat: input, animation playback for every
	combatant (locomotion included), impact feedback and camera work.

	Own actions are predicted: the animation and effects play the moment you
	press the key, and the server's Ack corrects it if the server disagrees.
]]

local CollectionService = game:GetService("CollectionService")
local ContextActionService = game:GetService("ContextActionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local CombatShared = ReplicatedStorage:WaitForChild("Combat")
local Config = require(CombatShared.Config)
local AnimationData = require(CombatShared.AnimationData)
local PoseAnimator = require(CombatShared.PoseAnimator)
local Effects = require(CombatShared.Effects)
local Motion = require(CombatShared.Motion)
local CameraFX = require(CombatShared.CameraFX)
local Remotes = CombatShared:WaitForChild("Remotes")

local player = Players.LocalPlayer
local camera = workspace.CurrentCamera
local FLAT = Vector3.new(1, 0, 1)

Effects.preload()
CameraFX.start()

------------------------------------------------------------------------
-- Animation playback (all combatants, run locally on every client)

-- Poses are played straight from AnimationData by PoseAnimator, so nothing
-- has to be uploaded and it behaves the same in Studio and live games.
local tracksByModel = {}

local function getTrack(model, name)
	if not model:FindFirstChildOfClass("Humanoid") then
		return nil
	end

	local tracks = tracksByModel[model]
	if not tracks then
		tracks = {}
		tracksByModel[model] = tracks
		model.Destroying:Once(function()
			tracksByModel[model] = nil
		end)
	end
	if tracks[name] then
		return tracks[name]
	end
	local track = PoseAnimator.get(model):track(name)

	local data = AnimationData[name]
	if data.markers and data.markers.Swing then
		local heavy = name == "Critical" or name == "Finisher"
		track:GetMarkerReachedSignal("Swing"):Connect(function()
			local root = model:FindFirstChild("HumanoidRootPart")
			if root then
				Effects.sound("Swing", root, heavy and 0.65 or 0.45, heavy and 0.8 or 1)
				-- your own strike leaving the windup nudges the camera with it
				if model == player.Character and root:IsA("BasePart") then
					CameraFX.punch(root.CFrame.LookVector, heavy and 0.35 or 0.12)
				end
			end
			local hitAt = data.markers.Hit or data.markers.Swing
			Effects.swingTrails(model, (hitAt - data.markers.Swing) + 0.1, data.trail)
		end)
	end

	tracks[name] = track
	return track
end

local REPLACES = {
	action = { action = true, react = true, hold = true },
	react = { action = true, react = true, hold = true },
	hold = { action = true },
}

local function stopGroups(model, groups, except)
	local tracks = tracksByModel[model]
	if not tracks then
		return
	end
	for name, track in pairs(tracks) do
		if name ~= except and track.IsPlaying and groups[AnimationData[name].group] then
			track:Stop(0.08)
		end
	end
end

local function isPlayingGroup(model, groups)
	local tracks = tracksByModel[model]
	if tracks then
		for name, track in pairs(tracks) do
			if track.IsPlaying and groups[AnimationData[name].group] then
				return true
			end
		end
	end
	return false
end

local function playAnim(model, name)
	local data = AnimationData[name]
	if not data then
		return
	end
	if data.variants then
		name = data.variants[math.random(1, #data.variants)]
		data = AnimationData[name]
	end

	local replaces = REPLACES[data.group]
	if replaces then
		stopGroups(model, replaces, name)
	end

	local track = getTrack(model, name)
	if track then
		local fade = data.group == "react" and 0.03 or 0.06
		if data.group == "hold" and track.IsPlaying then
			return
		end
		track:Play(fade, 1, 1)
	end
end

local function stopAnim(model, name)
	local tracks = tracksByModel[model]
	local track = tracks and tracks[name]
	if track and track.IsPlaying then
		track:Stop(0.1)
	end
end

local function stopFamily(model, name)
	-- hit reactions have variants; stopping the family stops whichever played
	stopAnim(model, name)
	local data = AnimationData[name]
	if data and data.variants then
		for _, variant in ipairs(data.variants) do
			stopAnim(model, variant)
		end
	end
end

Remotes.Anim.OnClientEvent:Connect(function(model, name, stop)
	if typeof(model) ~= "Instance" or not model.Parent or type(name) ~= "string" then
		return
	end
	if stop then
		stopFamily(model, name)
	else
		playAnim(model, name)
	end
end)

------------------------------------------------------------------------
-- Locomotion: idle / walk / run / jump / fall / land for every combatant,
-- picked from how the body is actually moving.

local locomotion = {}

local groundParams = RaycastParams.new()
groundParams.FilterType = Enum.RaycastFilterType.Exclude

local function refreshGroundFilter()
	local ignore = CollectionService:GetTagged("Combatant")
	local fx = workspace:FindFirstChild("CombatFX")
	if fx then
		table.insert(ignore, fx)
	end
	groundParams.FilterDescendantsInstances = ignore
end

local function isGrounded(humanoid, root, model)
	if model == player.Character then
		return humanoid.FloorMaterial ~= Enum.Material.Air
	end
	-- Other bodies: FloorMaterial isn't reliable for them here, so probe.
	return workspace:Raycast(root.Position, Vector3.new(0, -3.6, 0), groundParams) ~= nil
end

local function updateLocomotion(model, dt)
	local humanoid = model:FindFirstChildOfClass("Humanoid")
	local root = model:FindFirstChild("HumanoidRootPart")
	if not humanoid or not root or humanoid.Health <= 0 then
		return
	end

	local state = locomotion[model]
	if not state then
		state = { current = nil, airborneFor = 0, minVy = 0, stride = 0 }
		locomotion[model] = state
		model.Destroying:Once(function()
			locomotion[model] = nil
		end)
	end

	local stance = getTrack(model, "Stance")
	if stance and not stance.IsPlaying then
		stance:Play(0.2)
	end

	local velocity = root.AssemblyLinearVelocity
	local speed = (velocity * FLAT).Magnitude
	local grounded = isGrounded(humanoid, root, model)

	local want
	if not grounded then
		state.airborneFor += dt
		state.minVy = math.min(state.minVy, velocity.Y)
		if velocity.Y > 3 and state.current ~= "Fall" then
			want = "Jump"
		elseif state.airborneFor > 0.12 or velocity.Y < -8 then
			want = "Fall"
		else
			want = state.current
		end
	else
		-- landing
		if state.airborneFor > 0.25 then
			local impact = -state.minVy
			if impact > 22 then
				local strength = math.clamp((impact - 22) / 70, 0, 1)
				if not isPlayingGroup(model, { action = true, react = true }) then
					playAnim(model, "Land")
				end
				Effects.land(root.Position, strength)
				if model == player.Character then
					CameraFX.shake(0.08 + strength * 0.25)
					CameraFX.punch(-Vector3.yAxis, 0.25 + strength * 0.5)
				end
			end
		end
		state.airborneFor = 0
		state.minVy = 0

		if speed < 1.2 then
			want = nil
		elseif speed < Config.WalkSpeed + 3.5 then
			want = "Walk"
		else
			want = "Run"
		end
	end

	if want ~= state.current then
		if state.current then
			local old = getTrack(model, state.current)
			if old then
				old:Stop(state.current == "Jump" and 0.25 or 0.15)
			end
		end
		if want then
			local track = getTrack(model, want)
			if track then
				track:Play(want == "Fall" and 0.25 or 0.12)
			end
		end
		state.current = want
	end

	if want == "Walk" or want == "Run" then
		local track = getTrack(model, want)
		local data = AnimationData[want]
		if track and data.speedRef then
			track:AdjustSpeed(math.clamp(speed / data.speedRef, 0.55, 1.6))
		end
	end

	-- dust kicked up by sprinting feet
	if grounded and want == "Run" then
		state.stride += speed * dt
		if state.stride > 7.5 then
			state.stride = 0
			Effects.step(root.Position)
		end
	end
end

------------------------------------------------------------------------
-- Combatant setup

local function setupCombatant(model)
	task.spawn(function()
		local humanoid = model:WaitForChild("Humanoid", 10)
		if not humanoid then
			return
		end
		local track = getTrack(model, "Stance")
		if track then
			track:Play(0.2)
		end
		Effects.attachTrails(model)
	end)
end

CollectionService:GetInstanceAddedSignal("Combatant"):Connect(setupCombatant)
for _, model in ipairs(CollectionService:GetTagged("Combatant")) do
	setupCombatant(model)
end

-- Keeps state-driven tracks in sync: locomotion, and the block hold while
-- another combatant is blocking (late joiners and missed events recover).
local filterTimer = 0
RunService.Heartbeat:Connect(function(dt)
	filterTimer -= dt
	if filterTimer <= 0 then
		filterTimer = 1
		refreshGroundFilter()
	end

	for _, model in ipairs(CollectionService:GetTagged("Combatant")) do
		if model.Parent then
			updateLocomotion(model, dt)

			if model ~= player.Character then
				local blocking = model:GetAttribute("CombatState") == "Blocking"
				local block = getTrack(model, "Block")
				if block and blocking ~= block.IsPlaying then
					if blocking then
						block:Play(0.07)
					else
						block:Stop(0.1)
					end
				end
			end
		end
	end
end)

------------------------------------------------------------------------
-- Feedback

-- Physical reactions layered over the clips (degrees/second impulses).
local function hitDirection(attacker, defender)
	local a = attacker and attacker:FindFirstChild("HumanoidRootPart")
	local d = defender and defender:FindFirstChild("HumanoidRootPart")
	if not a or not d then
		return 1, 0
	end
	local from = d.CFrame:VectorToObjectSpace((d.Position - a.Position) * FLAT)
	if from.Magnitude < 0.01 then
		return 1, 0
	end
	from = from.Unit
	-- from.Z < 0: pushed backwards relative to the defender's facing
	return -from.Z, from.X
end

local function worldDirection(attacker, defender)
	local a = attacker and attacker:FindFirstChild("HumanoidRootPart")
	local d = defender and defender:FindFirstChild("HumanoidRootPart")
	if a and d then
		local dir = (d.Position - a.Position) * FLAT
		if dir.Magnitude > 0.05 then
			return dir.Unit
		end
	end
	return Vector3.zero
end

local function isModel(value)
	return typeof(value) == "Instance" and value.Parent ~= nil
end

local function react(kind, attacker, defender)
	local back, side = hitDirection(attacker, defender)
	local function kick(model, joint, p, y, r)
		if isModel(model) then
			PoseAnimator.kick(model, joint, Vector3.new(p, y, r))
		end
	end
	if kind == "Hit" or kind == "HeavyHit" then
		local m = kind == "HeavyHit" and 1.8 or 1.15
		kick(defender, "Torso", 300 * back * m, math.random(-160, 160), -200 * side * m)
		kick(defender, "Head", 420 * back * m, math.random(-260, 260), -120 * side * m)
		kick(defender, "RightArm", 260 * m, 0, 160 * m)
		kick(defender, "LeftArm", 260 * m, 0, -160 * m)
		kick(attacker, "Torso", -90, 0, 0)
		kick(attacker, "Head", -120, 0, 0)
	elseif kind == "Block" then
		kick(defender, "RightArm", -320, 0, 80)
		kick(defender, "LeftArm", -320, 0, -80)
		kick(defender, "Torso", 180, 0, 0)
		kick(attacker, "Torso", 120, 0, 0)
	elseif kind == "Parry" then
		kick(attacker, "Torso", 320, 0, 0)
		kick(attacker, "RightArm", 520, 0, 0)
		kick(attacker, "LeftArm", 520, 0, 0)
		kick(defender, "LeftArm", 300, 0, -120)
	elseif kind == "GuardBreak" then
		kick(defender, "Torso", 480, 0, 0)
		kick(defender, "Head", 600, 0, 0)
	elseif kind == "Slam" then
		kick(defender, "Torso", -420, 0, 0)
		kick(defender, "Head", -520, 0, 0)
	end
end

-- Both bodies freeze for a few frames when a hit connects.
local function hitStop(kind, attacker, defender)
	local duration = Config.HitStop[kind]
	if not duration then
		return
	end
	if isModel(defender) then
		PoseAnimator.hitStop(defender, duration, kind == "Block" and 0.1 or 0.28)
	end
	if isModel(attacker) then
		PoseAnimator.hitStop(attacker, duration, kind == "Parry" and 0.22 or 0)
	end
	if kind == "Parry" and isModel(defender) then
		playAnim(defender, "Deflect")
	end
end

local IMPACT_TINT = {
	Parry = Color3.fromRGB(255, 230, 170),
	GuardBreak = Color3.fromRGB(255, 190, 150),
}

-- Camera reaction, strongest for whoever is on the receiving end.
local function cameraReact(kind, amount, position, attacker, defender, info)
	local character = player.Character
	if not character then
		return
	end
	local direction = worldDirection(attacker, defender)
	local big = info == "Finisher" or info == "Critical"

	if defender == character then
		CameraFX.shake(amount)
		CameraFX.punch(direction, kind == "HeavyHit" and 0.9 or 0.5)
		if kind == "HeavyHit" or kind == "GuardBreak" then
			CameraFX.fovKick(big and 7 or 4)
			CameraFX.rollKick(math.random() < 0.5 and -5 or 5)
			CameraFX.impactFrame(big and 0.7 or 0.4, IMPACT_TINT[kind])
		elseif kind == "Parry" then
			CameraFX.fovKick(-3)
			CameraFX.impactFrame(0.35, IMPACT_TINT.Parry)
		end
	elseif attacker == character then
		CameraFX.shake(amount * 0.55)
		CameraFX.punch(direction, kind == "HeavyHit" and 0.45 or 0.22)
		if kind == "HeavyHit" or kind == "GuardBreak" then
			CameraFX.fovKick(big and -6 or -3)
			CameraFX.impactFrame(big and 0.8 or 0.35, IMPACT_TINT[kind])
			if big then
				CameraFX.blur(8)
			end
		elseif kind == "Parry" then
			CameraFX.shake(0.15)
			CameraFX.fovKick(4)
		elseif kind == "Hit" then
			CameraFX.fovKick(-1.2)
		end
	else
		-- spectating: only big impacts nearby reach the camera
		local root = character:FindFirstChild("HumanoidRootPart")
		if root and amount >= 0.4 then
			local falloff = math.clamp(1 - (root.Position - position).Magnitude / 45, 0, 1)
			CameraFX.shake(amount * 0.35 * falloff)
		end
	end
end

Remotes.Effect.OnClientEvent:Connect(function(kind, position, attacker, defender, info)
	if type(kind) ~= "string" or typeof(position) ~= "Vector3" then
		return
	end
	local character = player.Character

	-- movement effects: our own were already played when we pressed the key
	if kind == "Dash" then
		if isModel(attacker) and attacker ~= character then
			Effects.dash(attacker, typeof(info) == "Vector3" and info or Vector3.zero, false)
		end
		return
	elseif kind == "DoubleJump" then
		if isModel(attacker) and attacker ~= character then
			Effects.doubleJump(attacker)
		end
		return
	end

	react(kind, attacker, defender)
	hitStop(kind, attacker, defender)
	local amount = Effects.play(kind, position, attacker, defender, info)
	cameraReact(kind, amount, position, attacker, defender, info)
end)

------------------------------------------------------------------------
-- Aim assist: attacks, guards and side dashes turn toward the enemy you're
-- facing, so exchanges happen face to face.

local function findFocus(root, range)
	local look = camera.CFrame.LookVector * FLAT
	if look.Magnitude < 0.01 then
		return nil
	end
	look = look.Unit
	local cosLimit = math.cos(math.rad(Config.AimAssistAngle))
	local best, bestScore
	for _, model in ipairs(CollectionService:GetTagged("Combatant")) do
		if model ~= player.Character then
			local other = model:FindFirstChild("HumanoidRootPart")
			local humanoid = model:FindFirstChildOfClass("Humanoid")
			if other and humanoid and humanoid.Health > 0 then
				local offset = (other.Position - root.Position) * FLAT
				local distance = offset.Magnitude
				if distance > 0.1 and distance <= (range or Config.AimAssistRange) then
					local dot = look:Dot(offset.Unit)
					if dot >= cosLimit then
						local score = distance * (2 - dot)
						if not bestScore or score < bestScore then
							best, bestScore = other, score
						end
					end
				end
			end
		end
	end
	return best
end

------------------------------------------------------------------------
-- Local prediction

local sequence = 0
local pending = {}

local predicted = {
	combo = 0,
	lastM1 = 0,
	busyUntil = 0,
	attackHitAt = 0,
	attacking = false,
	parryReadyAt = 0,
	parryUntil = 0,
	feintReadyAt = 0,
	critReadyAt = 0,
	rollReadyAt = 0,
	rollStarted = 0,
	blockReadyAt = 0,
	blocking = false,
	lastBlockTry = 0,
	skillReadyAt = 0,
	doubleJumped = false,
	dashOrbit = nil,
	dashOrbitUntil = 0,
}

local blockPressedAt = 0

-- Space waits a beat before jumping so Space + M1 can launch instead.
local spaceDownAt = nil
local jumpConsumed = false

local sprinting = false
local blockHeld = false
local bufferedM1 = nil
local lastWPress = 0

local function getCharacter()
	local character = player.Character
	if not character then
		return nil
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local root = character:FindFirstChild("HumanoidRootPart")
	if not humanoid or not root or humanoid.Health <= 0 then
		return nil
	end
	return character, humanoid, root
end

local function serverState()
	local character = player.Character
	return character and character:GetAttribute("CombatState") or "Idle"
end

local function canPredictAction(t)
	return serverState() == "Idle" and t >= predicted.busyUntil and t > predicted.parryUntil
end

local function send(action, arg, predictedAnim, kind)
	sequence += 1
	if predictedAnim then
		pending[sequence] = { anim = predictedAnim, kind = kind }
	end
	Remotes.Action:FireServer(action, sequence, arg)
end

Remotes.Ack.OnClientEvent:Connect(function(id, accepted, anim)
	local entry = pending[id]
	pending[id] = nil
	local character = player.Character
	if not character then
		return
	end

	if entry and entry.kind == "block" then
		if not accepted then
			stopAnim(character, "Block")
		end
		return
	end

	if entry and entry.kind == "m1" then
		predicted.combo = character:GetAttribute("Combo") or predicted.combo
	end

	if entry then
		if not accepted then
			stopAnim(character, entry.anim)
			predicted.busyUntil = 0
			predicted.attacking = false
		elseif anim and anim ~= entry.anim then
			stopAnim(character, entry.anim)
			playAnim(character, anim)
		end
	elseif accepted and anim then
		playAnim(character, anim)
	end
end)

-- Past your own hit frame: block, parry and dash can cut the swing short.
local function inPredictedRecovery(t)
	return predicted.attacking and t > predicted.attackHitAt
end

local function predictAttack(kind)
	local attack = Config.Attacks[kind]
	local anim = AnimationData[attack.anim]
	local t = os.clock()
	predicted.busyUntil = t + anim.recover
	predicted.attackHitAt = t + anim.markers.Hit
	predicted.attacking = true
	return attack.anim
end

local function doM1()
	local character, humanoid, root = getCharacter()
	if not character then
		return
	end
	local t = os.clock()

	if not canPredictAction(t) then
		bufferedM1 = t
		return
	end
	bufferedM1 = nil

	local airborne = humanoid.FloorMaterial == Enum.Material.Air
	local launcher = not airborne and spaceDownAt ~= nil and UserInputService:IsKeyDown(Enum.KeyCode.Space)
	local speed = (root.AssemblyLinearVelocity * FLAT).Magnitude
	if launcher then
		jumpConsumed = true
	end

	if t - predicted.lastM1 > Config.ComboResetTime then
		predicted.combo = 0
	end

	local juggling = false
	if airborne then
		for _, model in ipairs(CollectionService:GetTagged("Combatant")) do
			local other = model:FindFirstChild("HumanoidRootPart")
			if model ~= character and other and model:GetAttribute("Juggled")
				and (other.Position - root.Position).Magnitude < 12 then
				juggling = true
				break
			end
		end
	end

	local kind
	if airborne then
		if juggling and predicted.combo + 1 < Config.ComboLength then
			kind = Config.AirChain[predicted.combo % #Config.AirChain + 1]
		else
			kind = "Downslam"
		end
	elseif launcher then
		kind = "Uppercut"
	elseif sprinting and speed > Config.WalkSpeed + 2 then
		kind = "RunningAttack"
	elseif predicted.combo + 1 >= Config.ComboLength then
		kind = "Finisher"
	else
		kind = Config.M1Chain[predicted.combo % #Config.M1Chain + 1]
	end

	predicted.combo += 1
	if Config.Attacks[kind].endsCombo then
		predicted.combo = 0
	end
	predicted.lastM1 = t
	sprinting = false

	local anim = predictAttack(kind)
	playAnim(character, anim)
	send("M1", { launcher = launcher, airborne = airborne }, anim, "m1")
end

local function doCritical()
	local character = getCharacter()
	if not character then
		return
	end
	local t = os.clock()
	if canPredictAction(t) and t >= predicted.critReadyAt then
		predicted.critReadyAt = t + Config.Attacks.Critical.cooldown
		sprinting = false
		local anim = predictAttack("Critical")
		playAnim(character, anim)
		CameraFX.fovKick(-2)
		send("Critical", nil, anim)
	else
		send("Critical")
	end
end

local function doFeint()
	local character, _, root = getCharacter()
	if not character then
		return
	end
	local t = os.clock()
	local state = serverState()

	local canFeintAttack = predicted.attacking
		and t < predicted.attackHitAt - Config.FeintLockout
		and t >= predicted.feintReadyAt
	local canCancelRoll = state == "Rolling" and t - predicted.rollStarted <= Config.RollCancelWindow

	if canFeintAttack then
		predicted.feintReadyAt = t + Config.FeintCooldown
		predicted.attacking = false
		predicted.busyUntil = t + 0.1
		playAnim(character, "Feint")
		send("Feint", nil, "Feint")
	elseif canCancelRoll then
		Motion.stop(root)
		playAnim(character, "Feint")
		send("Feint", nil, "Feint")
	else
		send("Feint")
	end
end

local function doBlock(resume)
	local character = getCharacter()
	if not character then
		return
	end
	local t = os.clock()
	local state = serverState()
	local recovering = inPredictedRecovery(t)
	predicted.lastBlockTry = t
	if t < predicted.blockReadyAt then
		return
	end
	if state ~= "Idle" and state ~= "Rolling" and state ~= "Parried" and not recovering then
		return
	end
	predicted.blocking = true

	-- Same pose either way: the press opens the parry window, holding blocks.
	if not resume and t >= predicted.parryReadyAt then
		predicted.parryReadyAt = t + Config.ParryCooldown
		predicted.parryUntil = t + Config.ParryWindow
	end
	if recovering then
		predicted.attacking = false
		predicted.busyUntil = t
	end
	sprinting = false
	playAnim(character, "Block")
	send("BlockDown", resume == true, "Block", "block")
end

local function releaseBlock()
	local character = player.Character
	if character then
		stopAnim(character, "Block")
	end
	if predicted.blocking then
		predicted.blockReadyAt = os.clock() + Config.BlockCooldown
	end
	predicted.blocking = false
	send("BlockUp")
end

-- Same choice the server makes in CombatService.dashAnim.
local function dashAnim(root, direction, airborne)
	if airborne then
		return "DashAir"
	end
	local relative = root.CFrame:VectorToObjectSpace(direction)
	if relative.Z < -0.5 then
		return "DashForward"
	elseif relative.Z > 0.5 then
		return "DashBack"
	elseif relative.X < 0 then
		return "DashLeft"
	end
	return "DashRight"
end

local function doRoll()
	local character, humanoid, root = getCharacter()
	if not character then
		return
	end
	local t = os.clock()
	local state = serverState()
	local recovering = inPredictedRecovery(t)
	if (state ~= "Idle" and state ~= "Blocking" and not recovering) or t < predicted.rollReadyAt then
		return
	end
	if recovering then
		predicted.attacking = false
		predicted.busyUntil = t
	end

	local move = humanoid.MoveDirection * FLAT
	local direction = move.Magnitude > 0.1 and move.Unit or (root.CFrame.LookVector * FLAT).Unit
	local airborne = humanoid.FloorMaterial == Enum.Material.Air
	local anim = dashAnim(root, direction, airborne)

	-- Side dashes near an opponent curve around them (Motion.dash orbit).
	predicted.dashOrbit = nil
	if anim == "DashLeft" or anim == "DashRight" then
		predicted.dashOrbit = findFocus(root, Config.DashOrbitRange)
		predicted.dashOrbitUntil = t + Config.RollDuration + 0.4
	end

	predicted.rollReadyAt = t + Config.RollCooldown
	predicted.rollStarted = t
	if state == "Blocking" then
		predicted.blockReadyAt = t + Config.BlockCooldown
		predicted.blocking = false
	end
	sprinting = false
	playAnim(character, anim)
	Effects.dash(character, direction, airborne)

	local sideways = root.CFrame:VectorToObjectSpace(direction).X
	CameraFX.fovKick(Config.Camera.DashFOV)
	CameraFX.rollKick(-sideways * Config.Camera.DashTilt)
	CameraFX.blur(5)
	send("Roll", { direction = direction, airborne = airborne }, anim)
end

local function tryDoubleJump()
	local character, _, root = getCharacter()
	if not character or predicted.doubleJumped then
		return false
	end
	local t = os.clock()
	if serverState() ~= "Idle" or t < predicted.busyUntil then
		return false
	end
	local state = locomotion[character]
	if not state or state.airborneFor < Config.DoubleJumpWindow then
		return false
	end
	predicted.doubleJumped = true
	local v = root.AssemblyLinearVelocity
	root.AssemblyLinearVelocity = Vector3.new(v.X, Config.DoubleJumpVelocity, v.Z)
	playAnim(character, "DoubleJump")
	Effects.doubleJump(character)
	CameraFX.fovKick(4)
	CameraFX.punch(Vector3.yAxis, 0.3)
	send("DoubleJump", nil, "DoubleJump")
	return true
end

local function doSkill()
	local character = getCharacter()
	if not character then
		return
	end
	local t = os.clock()
	if canPredictAction(t) and t >= predicted.skillReadyAt then
		predicted.skillReadyAt = t + Config.Skill.cooldown
		predicted.busyUntil = t + Config.Skill.castTime
		predicted.attackHitAt = t + Config.Skill.release
		predicted.attacking = true
		sprinting = false
		playAnim(character, "SkillCast")
		send("Skill", nil, "SkillCast")
	end
end

local function setSprint(on)
	if sprinting == on then
		return
	end
	sprinting = on
	send("Sprint", on)
end

Remotes.Impulse.OnClientEvent:Connect(function(kind, velocity, duration, delay)
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root or type(kind) ~= "string" or typeof(velocity) ~= "Vector3" then
		return
	end
	local orbit = nil
	if kind == "dash" and predicted.dashOrbit and os.clock() < predicted.dashOrbitUntil then
		orbit = predicted.dashOrbit
	end
	Motion.apply(root, kind, velocity, duration, delay, orbit)
end)

------------------------------------------------------------------------
-- Input

local shiftLocked = false

local function toggleShiftLock()
	shiftLocked = not shiftLocked
	if not shiftLocked then
		UserInputService.MouseBehavior = Enum.MouseBehavior.Default
	end
end

-- Space: jump after a short buffer unless an M1 turns it into a launcher;
-- in the air it's the double jump.
ContextActionService:BindActionAtPriority("CombatJump", function(_, inputState)
	if inputState ~= Enum.UserInputState.Begin then
		return Enum.ContextActionResult.Sink
	end
	local _, humanoid = getCharacter()
	if humanoid and humanoid.FloorMaterial == Enum.Material.Air then
		tryDoubleJump()
		return Enum.ContextActionResult.Sink
	end

	local pressedAt = os.clock()
	spaceDownAt = pressedAt
	jumpConsumed = false
	task.delay(Config.LauncherBuffer, function()
		if spaceDownAt ~= pressedAt or jumpConsumed then
			return
		end
		local _, h = getCharacter()
		-- ChangeState rather than .Jump: the default control script rewrites
		-- .Jump every frame, and Space is sunk so it never sees the press.
		if h and serverState() == "Idle" and h.JumpHeight > 0
			and h.FloorMaterial ~= Enum.Material.Air then
			h:ChangeState(Enum.HumanoidStateType.Jumping)
		end
	end)
	return Enum.ContextActionResult.Sink
end, false, Enum.ContextActionPriority.High.Value, Enum.KeyCode.Space)

UserInputService.InputEnded:Connect(function(input)
	if input.KeyCode == Enum.KeyCode.Space then
		task.delay(Config.LauncherBuffer + 0.02, function()
			if not UserInputService:IsKeyDown(Enum.KeyCode.Space) then
				spaceDownAt = nil
			end
		end)
	end
end)

UserInputService.InputBegan:Connect(function(input, processed)
	if processed then
		return
	end

	if input.UserInputType == Enum.UserInputType.MouseButton1 then
		doM1()
	elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
		doFeint()
	elseif input.KeyCode == Enum.KeyCode.R then
		doCritical()
	elseif input.KeyCode == Enum.KeyCode.F then
		blockHeld = true
		blockPressedAt = os.clock()
		doBlock(false)
	elseif input.KeyCode == Enum.KeyCode.Y then
		doSkill()
	elseif input.KeyCode == Enum.KeyCode.Q then
		doRoll()
	elseif input.KeyCode == Enum.KeyCode.LeftAlt or input.KeyCode == Enum.KeyCode.RightAlt then
		toggleShiftLock()
	elseif input.KeyCode == Enum.KeyCode.W then
		local t = os.clock()
		if t - lastWPress <= Config.SprintDoubleTapWindow then
			setSprint(true)
		end
		lastWPress = t
	end
end)

UserInputService.InputEnded:Connect(function(input)
	if input.KeyCode == Enum.KeyCode.F then
		if blockHeld then
			blockHeld = false
			releaseBlock()
		end
	elseif input.KeyCode == Enum.KeyCode.W then
		setSprint(false)
	end
end)

------------------------------------------------------------------------
-- State follow-up: buffering, block resume

local function onStateChanged(character)
	local state = character:GetAttribute("CombatState")

	if state == "Stunned" or state == "Parried" or state == "GuardBroken" then
		predicted.combo = 0
		predicted.attacking = false
		predicted.busyUntil = 0
		sprinting = false
		bufferedM1 = nil
	end
	if state == "GuardBroken" then
		predicted.blocking = false
		predicted.blockReadyAt = os.clock() + Config.GuardBreakStun + Config.BlockCooldown
	end
	if state ~= "Blocking" and predicted.blocking and not blockHeld then
		predicted.blocking = false
	end

	if state == "Idle" then
		predicted.attacking = false
		if blockHeld then
			-- F pressed late in a stun still comes out as a parry the moment it ends
			doBlock(os.clock() - blockPressedAt > Config.BlockBuffer)
		elseif bufferedM1 and os.clock() - bufferedM1 <= Config.InputBufferTime then
			doM1()
		end
	end
end

local function onCharacterAdded(character)
	predicted.combo = 0
	predicted.busyUntil = 0
	predicted.attacking = false
	predicted.doubleJumped = false
	sprinting = false
	blockHeld = false

	character:GetAttributeChangedSignal("CombatState"):Connect(function()
		onStateChanged(character)
	end)

	-- PoseAnimator drives the whole body; Roblox's default animations would
	-- only fight it. The server removes Animate already; this covers setups
	-- that spawn characters some other way.
	local function removeAnimate(child)
		if child.Name == "Animate" and (child:IsA("LocalScript") or child:IsA("Script")) then
			child:Destroy()
		end
	end
	for _, child in ipairs(character:GetChildren()) do
		removeAnimate(child)
	end
	character.ChildAdded:Connect(removeAnimate)
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		for _, playing in ipairs(animator:GetPlayingAnimationTracks()) do
			playing:Stop(0)
		end
	end
end

player.CharacterAdded:Connect(onCharacterAdded)
if player.Character then
	task.spawn(onCharacterAdded, player.Character)
end

RunService.Heartbeat:Connect(function()
	local character, humanoid = getCharacter()
	if not character then
		return
	end

	local t = os.clock()
	if bufferedM1 and t - bufferedM1 > Config.InputBufferTime then
		bufferedM1 = nil
	elseif bufferedM1 and canPredictAction(t) then
		doM1()
	end

	-- Holding F through a block cooldown (or a stun) brings the guard back up.
	if blockHeld and serverState() == "Idle" and t >= predicted.blockReadyAt
		and not predicted.attacking and t - predicted.lastBlockTry > 0.03 then
		doBlock(true)
	end

	-- Touching the ground gives the double jump back.
	if humanoid.FloorMaterial ~= Enum.Material.Air then
		predicted.doubleJumped = false
	end
end)

-- Anyone held by the slash skill gets cut from every angle until released.
local nextCut = {}
RunService.Heartbeat:Connect(function()
	local t = os.clock()
	for _, model in ipairs(CollectionService:GetTagged("Combatant")) do
		if model:GetAttribute("Dismantled") then
			if t >= (nextCut[model] or 0) then
				nextCut[model] = t + math.random(45, 85) / 1000
				Effects.dismantleCut(model)
				local joints = { "Torso", "Head", "RightArm", "LeftArm" }
				PoseAnimator.kick(model, joints[math.random(1, #joints)],
					Vector3.new(math.random(-380, 380), math.random(-260, 260), math.random(-300, 300)))
				if model == player.Character then
					CameraFX.shake(0.12)
				end
			end
		else
			nextCut[model] = nil
		end
	end
end)

------------------------------------------------------------------------
-- Rotation and shift lock (Alt). Shake, FOV and tilt live in CameraFX.

-- You keep turning freely while attacking, blocking and dashing. Only hard
-- stuns take rotation away.
local ROTATION_LOCKED = { Stunned = true, Parried = true, GuardBroken = true, Captured = true, Kneeling = true }

RunService:BindToRenderStep("CombatCamera", Enum.RenderPriority.Camera.Value + 1, function(dt)
	local character, humanoid, root = getCharacter()
	if not character then
		return
	end

	-- Characters are spawned by the server, so the default camera can stay
	-- attached to the old body after a respawn. Always follow the live one.
	camera = workspace.CurrentCamera
	if camera.CameraSubject ~= humanoid then
		camera.CameraSubject = humanoid
		camera.CameraType = Enum.CameraType.Custom
	end

	local offset = Vector3.zero
	local state = serverState()
	local rotationLocked = ROTATION_LOCKED[state] == true
	local t = os.clock()

	local focus
	if not rotationLocked and state == "Rolling" and predicted.dashOrbit
		and predicted.dashOrbit.Parent and t < predicted.dashOrbitUntil then
		-- face the opponent while circling them
		focus = predicted.dashOrbit
	else
		local engaged = predicted.attacking or state == "Attacking" or state == "Blocking"
		focus = engaged and not rotationLocked and not shiftLocked and findFocus(root)
	end

	if focus then
		humanoid.AutoRotate = false
		local position = root.Position
		local goal = CFrame.lookAt(position, Vector3.new(focus.Position.X, position.Y, focus.Position.Z))
		root.CFrame = root.CFrame:Lerp(goal, 1 - math.exp(-Config.AimAssistTurnRate * dt))
	elseif shiftLocked then
		UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
		offset += Config.ShiftLockOffset
		humanoid.AutoRotate = false
		if not rotationLocked then
			local look = camera.CFrame.LookVector * FLAT
			if look.Magnitude > 0.01 then
				local position = root.Position
				root.CFrame = CFrame.lookAt(position, position + look.Unit)
			end
		end
	else
		humanoid.AutoRotate = not rotationLocked
	end

	humanoid.CameraOffset = offset
end)
