	{ name = "AnimationData", class = "ModuleScript", home = "combat" },
	{ name = "CameraFX", class = "ModuleScript", home = "combat" },
	{ name = "Config", class = "ModuleScript", home = "combat" },
	{ name = "Effects", class = "ModuleScript", home = "combat" },
	{ name = "Motion", class = "ModuleScript", home = "combat" },
	{ name = "PoseAnimator", class = "ModuleScript", home = "combat" },
